from app.providers import services, tmdb
from app.templatetags.app_extras import slug

logger = logging.getLogger(__name__)

MEDIA_TYPES = ["movie", "tv", "season", "episode", "anime", "manga", "game"]
READABLE_MEDIA_TYPES = {
    "movie": "Movie",
