                name = f"{base_name} {i}"
                slug = f"{base_slug}-{i}"

                if slug.lower() in existing_slugs or name.lower() in existing_names:
                    continue
                break
        existing_slugs.add(slug.lower())
        existing_names.add(name.lower())

        # Fill in remaining attributes
