class ApiErrorView(views.APIView):
    authentication_classes = []
    permission_classes = (permissions.AllowAny,)
    metadata_class = None
    exception_class = exceptions.APIException

    name = _('API Error')

    def finalize_response(self, request, response, *args, **kwargs):
