    reusable_media = models.BooleanField(default=False)

    class Meta:
        unique_together = (('issuer', 'acceptor'),)


class GiftCard(LoggedModel):
    issuer = models.ForeignKey(
        'Organizer',
        related_name='issued_gift_cards',
        on_delete=models.PROTECT,
    )
