    if data is None:
        url = f"{base_url}/search/{media_type}"

        params = {
            **base_params,
            "query": query,
        }

        if settings.TMDB_NSFW:
            params["include_adult"] = "true"

        response = services.api_request("TMDB", "GET", url, params=params)

        response = response["results"]
        data = [
            {
                "media_id": media["id"],
                "source": "tmdb",
                "media_type": media_type,
