            if data["start_time"] >= data["end_time"]:
                return error_response(u"比赛的开始时间必须早于比赛结束的时间")

            # 之前是封榜，现在要开放，需要清除缓存
            if contest.real_time_rank == False and data["real_time_rank"] == True:
                r = get_cache_redis()
                cache_key = str(contest.id) + "_rank_cache"
