            if request.user.admin_type != SUPER_ADMIN and contest.created_by != request.user:
                return error_response(u"您无权查看该信息!")
            submissions = Submission.objects.filter(contest_id=contest_id).order_by("-create_time")
        else:
            if problem_id:
