                    request.user.admin_type == SUPER_ADMIN or \
                    request.user == contest.created_by:
        show_submit_code_area = True
    else:
        contest_set = Contest.objects.filter(groups__in=request.user.managed_groups.all())
        if contest in contest_set:
            show_submit_code_area = True
