            select_related("user"). \
            order_by("-total_ac_number", "total_time"). \
            values("id", "user__id", "user__username", "user__real_name", "user__userprofile__student_id",
                   "contest_id", "submission_info", "total_submission_number", "total_ac_number", "total_time")
    return rank


