                proc = int(ceil(choice["votes"] * 100 / self.votes))
            else:
                proc = 0

            view_choices.append(
                {
                    "label": choice["label"],
                    "votes": choice["votes"],
                    "selected": choice["selected"],
                    "proc": proc,
                }
            )
        return view_choices

