    thread: Thread,
    post: Post,
):
    check_edit_thread_post_permission_hook(
        _check_edit_thread_post_permission_action, permissions, category, thread, post
    )


def _check_edit_thread_post_permission_action(
    permissions: UserPermissionsProxy,
