        return urljoin(settings.TOWER_URL_BASE, "{}/jobs/command/{}".format(settings.OPTIONAL_UI_URL_PREFIX, self.pk))

    @property
    def notification_templates(self):
        all_orgs = {h.inventory.organization for h in self.hosts.all()}
        active_templates = dict(error=set(), success=set(), started=set())
        base_notification_templates = NotificationTemplate.objects
        for org in all_orgs:
            for templ in base_notification_templates.filter(organization_notification_templates_for_errors=org):
                active_templates['error'].add(templ)
            for templ in base_notification_templates.filter(organization_notification_templates_for_success=org):
                active_templates['success'].add(templ)
            for templ in base_notification_templates.filter(organization_notification_templates_for_started=org):
                active_templates['started'].add(templ)
        active_templates['error'] = list(active_templates['error'])
        active_templates['success'] = list(active_templates['success'])
        active_templates['started'] = list(active_templates['started'])
        return active_templates

    def get_passwords_needed_to_start(self):
        return self.passwords_needed_to_start

    def _get_task_impact(self):
        # NOTE: We sorta have to assume the host count matches and that forks default to 5
        if self.inventory:
            count_hosts = self.inventory.total_hosts
        else:
            count_hosts = 5
        return min(count_hosts, 5 if self.forks == 0 else self.forks) + 1

    def copy(self):
        data = {}
        for field in (
            'job_type',
            'inventory_id',
            'limit',
            'credential_id',
            'execution_environment_id',
            'module_name',
            'module_args',
            'forks',
            'verbosity',
            'extra_vars',
            'become_enabled',
            'diff_mode',
        ):
            data[field] = getattr(self, field)
        return AdHocCommand.objects.create(**data)

    def save(self, *args, **kwargs):
        update_fields = kwargs.get('update_fields', [])

        def add_to_update_fields(name):
            if name not in update_fields:
                update_fields.append(name)

        if not self.preferred_instance_groups_cache:
            self.preferred_instance_groups_cache = self._get_preferred_instance_group_cache()
            add_to_update_fields("preferred_instance_groups_cache")
        if not self.name:
            self.name = Truncator(u': '.join(filter(None, (self.module_name, self.module_args)))).chars(512)
            add_to_update_fields("name")
        if self.task_impact == 0:
            self.task_impact = self._get_task_impact()
            add_to_update_fields("task_impact")
        super(AdHocCommand, self).save(*args, **kwargs)

    @property
    def preferred_instance_groups(self):
        selected_groups = []
        if self.inventory is not None:
            for instance_group in self.inventory.instance_groups.all():
                selected_groups.append(instance_group)
            if not self.inventory.prevent_instance_group_fallback and self.inventory.organization is not None:
                for instance_group in self.inventory.organization.instance_groups.all():
                    selected_groups.append(instance_group)

        if not selected_groups:
            return self.global_instance_groups
        return selected_groups

    '''
    JobNotificationMixin
    '''

    def get_notification_templates(self):
        return self.notification_templates

    def get_notification_friendly_name(self):
        return "AdHoc Command"

