  const submit = async () => {
    if (!submitLoader) {
      setSubmitLoader(true);

      await deleteUser.mutateAsync(userId, {
        onSuccess: () => {
          onClose();
        },
        onSettled: (data, error) => {
          setSubmitLoader(false);
        },
