import { UseFilters, UseGuards } from "@nestjs/common";
import { Resolver, Query, Args, Parent, ResolveField } from "@nestjs/graphql";
import { GqlAuthGuard } from "../../guards/gql-auth.guard";
import { GqlResolverExceptionsFilter } from "../../filters/GqlResolverExceptions.filter";
import { AuthorizeContext } from "../../decorators/authorizeContext.decorator";
import { AuthorizableOriginParameter } from "../../enums/AuthorizableOriginParameter";
import { UserAction } from "./dto";
import { FindOneUserActionArgs } from "./dto/FindOneUserActionArgs";
import { UserActionService } from "./userAction.service";
import { EnumUserActionStatus } from "./types";
import { Action } from "../action/dto";
import { ActionService } from "../action/action.service";
import { UserService } from "../user/user.service";
import { ResourceService } from "../resource/resource.service";
import { Resource, User } from "../../models";

@Resolver(() => UserAction)
@UseFilters(GqlResolverExceptionsFilter)
@UseGuards(GqlAuthGuard)
export class UserActionResolver {
  constructor(
    private readonly userActionService: UserActionService,
    private readonly actionService: ActionService,
    private readonly userService: UserService,
    private readonly resourceService: ResourceService
  ) {}

  @Query(() => UserAction)
  @AuthorizeContext(AuthorizableOriginParameter.UserActionId, "where.id")
  async userAction(@Args() args: FindOneUserActionArgs): Promise<UserAction> {
    return this.userActionService.findOne(args);
  }

  @ResolveField()
  status(@Parent() userAction: UserAction): Promise<EnumUserActionStatus> {
    return this.userActionService.calcUserActionStatus(userAction.id);
  }

  @ResolveField()
  async action(@Parent() userAction: UserAction): Promise<Action> {
    return this.actionService.findOne({ where: { id: userAction.actionId } });
  }

  @ResolveField()
  async resource(@Parent() userAction: UserAction): Promise<Resource> {
    return this.resourceService.resource({
      where: { id: userAction.resourceId },
    });
  }

  @ResolveField()
  async user(@Parent() userAction: UserAction): Promise<User> {
    return this.userService.findUser(
      { where: { id: userAction.userId } },
      true
    );
  }
}

import { Injectable } from "@nestjs/common";
import { Prisma, PrismaService } from "../../prisma";
import { FindOneUserActionArgs } from "./dto/FindOneUserActionArgs";
import { UserAction } from "./dto";
import { EnumActionStepStatus } from "../action/dto";
import { EnumUserActionStatus, EnumUserActionType } from "./types";
import { ActionService } from "../action/action.service";

@Injectable()
export class UserActionService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly actionService: ActionService
  ) {}

  async findOne(args: FindOneUserActionArgs): Promise<UserAction | null> {
    return this.prisma.userAction.findUnique(args);
  }

  async createUserActionByTypeWithInitialStep(
    userActionType: EnumUserActionType,
    metadata: Record<string, any>, // provide the exact type when calling this method
    initialStepData: Prisma.ActionStepCreateWithoutActionInput,
    userId: string,
    resourceId?: string
  ): Promise<UserAction> {
    const data: Prisma.UserActionCreateInput = {
      userActionType,
      metadata,
      user: {
        connect: {
          id: userId,
        },
      },
      action: {
        create: {
          steps: {
            create: initialStepData,
          },
        },
      },
    };

    if (resourceId) {
      data.resource = {
        connect: {
          id: resourceId,
        },
      };
    }

    return await this.prisma.userAction.create({
      data,
    });
  }

  async calcUserActionStatus(
    userActionId: string
  ): Promise<EnumUserActionStatus> {
    const userAction = await this.prisma.userAction.findUnique({
      where: {
        id: userActionId,
      },
      include: {
        action: {
          include: {
            steps: true,
          },
        },
      },
    });

    if (!userAction.action?.steps?.length) return EnumUserActionStatus.Invalid;

    const steps = userAction.action.steps;

    if (steps.every((step) => step.status === EnumActionStepStatus.Success))
      return EnumUserActionStatus.Completed;

    if (steps.some((step) => step.status === EnumActionStepStatus.Failed))
      return EnumUserActionStatus.Failed;

    return EnumUserActionStatus.Running;
  }

  async updateUserActionMetadata(
    userActionId: string,
    actionStepName: string,
    status: EnumActionStepStatus.Success | EnumActionStepStatus.Failed,
    metadata: any
  ): Promise<UserAction> {
    const userAction = await this.prisma.userAction.findUnique({
      where: {
        id: userActionId,
      },
      include: {
        action: {
          include: {
            steps: {
              where: {
                name: actionStepName,
              },
              orderBy: {
                createdAt: "desc",
              },
            },
          },
        },
      },
    });
    await this.actionService.complete(userAction.action.steps[0], status);

    await this.prisma.userAction.update({
      where: {
        id: userActionId,
      },
      data: {
        metadata,
      },
    });

    return userAction;
  }
}

import { EnumUserActionStatus } from "./types";

export interface UserActionResultWithPayload<T> {
  status: EnumUserActionStatus;
  data: T | null;
}

import { FileUpload } from "graphql-upload";

export async function graphqlUpload(file: FileUpload) {
  const chunks = [];
  for await (const chunk of file.createReadStream()) {
    chunks.push(chunk);
  }
  const fileBuffer = Buffer.concat(chunks);
  const fileContent = fileBuffer.toString("utf8");

  return fileContent;
}

