    {
      onCompleted: (data) => {
        pendingChangesContext.addBlock(data.updateServiceSettings.id);
      },
    }
  );

  const { handleSubmit, FORM_SCHEMA } = useSettingsHook({
    trackEvent,
    resourceId,
    updateServiceSettings,
  });

