  const filePath = isPreview
    ? `archives/preview/${collection.id}/${linkId}.jpeg`
    : `archives/${collection.id}/${linkId + suffix}`;

  return {
    status: 200,
    response: {
      filePath,
      collectionId: collection.id,
      linkId,
      format: format as ArchivedFormat,
      isPreview,
    },
  };
}

