  accountId?: string;
  onDialogClose: () => void;
};

export function NewOpportunityForm({
  accounts,
  contacts,
  salesType,
  saleStages,
  campaigns,
  currencies,
  selectedStage,
  accountId,
  onDialogClose,
}: NewTaskFormProps) {
  const t = useTranslations("CrmOpportunityForm");
  const c = useTranslations("Common");

  const [searchAccountValue, setSearchAccountValue] = useState<string>("");
  const [searchContactValue, setSearchContactValue] = useState<string>("");

  const filteredAccounts = useMemo(
    () =>
      accounts.filter((account) =>
        account.name.toLowerCase().includes(searchAccountValue.toLowerCase())
      ),
    [accounts, searchAccountValue]
  );

  const filteredContacts = useMemo(
    () =>
      contacts.filter(
        (contact) =>
          contact.last_name
            .toLowerCase()
            .includes(searchContactValue.toLowerCase()) ||
          (contact.first_name &&
            contact.first_name
              .toLowerCase()
              .includes(searchContactValue.toLowerCase()))
      ),
    [contacts, searchContactValue]
  );

  const formSchema = z.object({
    name: z.string().min(1, t("nameRequired")),
    close_date: z.date({
      message: "A expected close date is required.",
    }),
    description: z.string(),
    type: z.string(),
    sales_stage: z.string(),
    budget: z.string(),
    currency: z.string(),
    expected_revenue: z.string(),
    next_step: z.string(),
    assigned_to: z.string(),
    account: z.string(),
    contact: z.string(),
    campaign: z.string(),
  });

  type NewAccountFormValues = z.infer<typeof formSchema>;

  const form = useForm<NewAccountFormValues>({
    resolver: zodResolver(formSchema),
    mode: "onBlur",
    defaultValues: {
      sales_stage: selectedStage ? selectedStage : "",
      account: accountId ? accountId : "",
      type: "",
      budget: "",
      currency: "",
      expected_revenue: "",
      next_step: "",
      assigned_to: "",
      contact: "",
      campaign: "",
      description: "",
      name: "",
    },
  });

  const onSubmit = async (data: NewAccountFormValues) => {
    const result = await createOpportunity(data);
    if (result?.error) {
      form.setError("root.serverError", { message: result.error || t("createError") });
    } else {
      toast.success(t("createSuccess"));
      form.reset({
        name: "",
        close_date: new Date(),
        description: "",
        type: "",
        sales_stage: "",
        budget: "",
        currency: "",
        expected_revenue: "",
        next_step: "",
        assigned_to: "",
        account: "",
        contact: "",
        campaign: "",
      });
      onDialogClose();
    }
  };

  return (
    <Form {...form}>
      <form
        onSubmit={form.handleSubmit(onSubmit)}
        className="w-full h-full px-4 md:px-10"
      >
        <div className="w-full text-sm">
          <div className="pb-5 space-y-2">
            <FormField
              control={form.control}
              name="name"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t("name")}</FormLabel>
                  <FormControl>
                    <Input
                      disabled={form.formState.isSubmitting}
                      placeholder="New NextCRM functionality"
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="close_date"
              render={({ field }) => (
                <FormItem className="flex flex-col">
                  <FormLabel>{t("closeDate")}</FormLabel>
                  <Popover>
                    <PopoverTrigger asChild>
                      <FormControl>
                        <Button
                          variant={"outline"}
                          className={cn(
                            "w-[240px] pl-3 text-left font-normal",
                            !field.value && "text-muted-foreground"
                          )}
                        >
                          {field.value ? (
                            format(field.value, "PPP")
                          ) : (
                            <span>{t("closeDatePlaceholder")}</span>
                          )}
                          <CalendarIcon className="ml-auto h-4 w-4 opacity-50" />
                        </Button>
                      </FormControl>
                    </PopoverTrigger>
                    <PopoverContent className="w-auto p-0" align="start">
                      <Calendar
                        mode="single"
                        selected={field.value}
                        //@ts-ignore
                        //TODO: fix this
                        onSelect={field.onChange}
                        disabled={(date) => date < new Date("1900-01-01")}
                        initialFocus
                      />
                    </PopoverContent>
                  </Popover>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="description"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{c("description")}</FormLabel>
                  <FormControl>
                    <Textarea
                      disabled={form.formState.isSubmitting}
                      placeholder="New NextCRM functionality"
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <FormField
                  control={form.control}
                  name="type"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>{t("salesType")}</FormLabel>
                      <Select
                        onValueChange={field.onChange}
                        defaultValue={field.value}
                      >
                        <FormControl>
                          <SelectTrigger>
                            <SelectValue placeholder={t("salesTypePlaceholder")} />
