  const { id: teamId } = req.query;

  if (req.method === 'GET') {
    if (!(await allowQuery(req, UmamiApi.AuthType.Team))) {
      return unauthorized(res);
    }
    const user = await getTeam({ id: teamId });

    return ok(res, user);
