      title: true,
      workEmail: true,
      user: {
        select: {
          name: true,
          email: true,
          image: true,
        },
      },
    },
  });

  if (!memberData?.user.name || !memberData.user.email) {
    throw new TRPCError({
      code: "BAD_REQUEST",
      message: "Something went wrong.",
    });
  }

  const { name, email, image } = memberData.user ?? {};

  const { title, workEmail } = memberData ?? {};

  const payload = {
    fullName: name ?? "",
    jobTitle: title ?? "",
    loginEmail: email ?? "",
    workEmail: workEmail ?? "",
    avatarUrl: image ?? "",
  };

  return payload;
});

import { withAuth } from "@/trpc/api/trpc";
import { ZodInviteMemberMutationSchema } from "../schema";
import {
  generateInviteToken,
  generateMemberIdentifier,
  sendMemberInviteEmail,
} from "@/server/member";
import { TRPCError } from "@trpc/server";
import { Audit } from "@/server/audit";

export const inviteMemberProcedure = withAuth
  .input(ZodInviteMemberMutationSchema)
  .mutation(async ({ ctx, input }) => {
    const user = ctx.session.user;
    const { name, email, title } = input;
    const { userAgent, requestIp } = ctx;

    //token flow same as https://github.com/nextauthjs/next-auth/blob/main/packages/core/src/lib/actions/signin/send-token.ts#L12C4-L12C4
    const { authTokenHash, expires, memberInviteTokenHash, token } =
      await generateInviteToken();

    const { company, verificationToken } = await ctx.db.$transaction(
      async (tx) => {
        const company = await tx.company.findFirstOrThrow({
          where: {
            id: user.companyId,
          },
          select: {
            name: true,
            id: true,
          },
        });

        // create or find user
        const invitedUser = await tx.user.upsert({
          where: {
            email,
          },
          update: {},
          create: {
            name,
            email,
          },
          select: {
            id: true,
          },
        });

        // check if user is already a member
        const prevMember = await tx.member.findUnique({
          where: {
            companyId_userId: {
              companyId: user.companyId,
              userId: invitedUser.id,
            },
          },
        });

        // if already a member, throw error
        if (prevMember && prevMember.status === "ACTIVE") {
          throw new TRPCError({
            code: "FORBIDDEN",
            message: "user already a member",
          });
        }

        //  create member
        const member = await tx.member.upsert({
          create: {
            title,
            isOnboarded: false,
            lastAccessed: new Date(),
            companyId: user.companyId,
            userId: invitedUser.id,
            status: "PENDING",
          },
          update: {
            title,
            isOnboarded: false,
            lastAccessed: new Date(),
            status: "PENDING",
          },
          where: {
            companyId_userId: {
              companyId: user.companyId,
              userId: invitedUser.id,
            },
          },
          select: {
            id: true,
            userId: true,
            user: {
              select: {
                name: true,
              },
            },
          },
        });

        // custom verification token for member invitation
        const { token: verificationToken } = await tx.verificationToken.create({
          data: {
            identifier: generateMemberIdentifier({
              email,
              memberId: member.id,
            }),
            token: memberInviteTokenHash,
            expires,
          },
        });

        // next-auth verification token
        await tx.verificationToken.create({
          data: {
            identifier: email,
            token: authTokenHash,
            expires,
          },
        });

        await Audit.create(
          {
            action: "member.invited",
            companyId: company.id,
            actor: { type: "user", id: user.id },
            context: {
              requestIp,
              userAgent,
            },
            target: [{ type: "user", id: member.userId }],
            summary: `${user.name} invited ${member.user?.name} to join ${company.name}`,
          },
          tx,
        );

        return { verificationToken, company };
      },
    );

    await sendMemberInviteEmail({
      verificationToken,
      token,
      email,
      company,
      user: {
        email: user.email,
        name: user.name,
      },
    });

    return { success: true };
  });

import { withAuth } from "@/trpc/api/trpc";
import { ZodReInviteMutationSchema } from "../schema";
import {
  generateInviteToken,
  generateMemberIdentifier,
  revokeExistingInviteTokens,
  sendMemberInviteEmail,
} from "@/server/member";
import { Audit } from "@/server/audit";

export const reInviteProcedure = withAuth
  .input(ZodReInviteMutationSchema)
  .mutation(async ({ ctx: { session, db, requestIp, userAgent }, input }) => {
    const user = session.user;
    const companyId = user.companyId;

    const { authTokenHash, expires, memberInviteTokenHash, token } =
      await generateInviteToken();

    const { company, verificationToken, email } = await db.$transaction(
      async (tx) => {
        const company = await tx.company.findFirstOrThrow({
          where: {
            id: companyId,
          },
          select: {
            name: true,
            id: true,
          },
        });

        const member = await tx.member.findFirstOrThrow({
          where: {
            id: input.memberId,
            status: "PENDING",
            companyId,
          },

          include: {
            user: {
              select: {
                name: true,
                email: true,
              },
            },
          },
        });

        const email = member.user.email;

        if (!email) {
          throw new Error("invited email not found");
        }

        await revokeExistingInviteTokens({
          memberId: member.id,
          email,
          tx,
        });

        // custom verification token for member invitation
        const { token: verificationToken } = await tx.verificationToken.create({
          data: {
            identifier: generateMemberIdentifier({
              email,
              memberId: member.id,
            }),
            token: memberInviteTokenHash,
            expires,
          },
        });

        // next-auth verification token
        await tx.verificationToken.create({
          data: {
            identifier: email,
            token: authTokenHash,
            expires,
          },
        });

        await Audit.create(
          {
            action: "member.re-invited",
            companyId: company.id,
            actor: { type: "user", id: user.id },
            context: {
              requestIp,
              userAgent,
            },
            target: [{ type: "user", id: member.userId }],
            summary: `${user.name} reinvited ${member.user?.name} to join ${company.name}`,
          },
          tx,
        );

        return { verificationToken, company, email };
      },
    );

    await sendMemberInviteEmail({
      verificationToken,
      token,
      email,
      company,
      user: {
        email: user.email,
        name: user.name,
      },
    });

    return { success: true };
  });

import { type withAuthTrpcContextType, withAuth } from "@/trpc/api/trpc";
import {
  type TypeZodRemoveMemberMutationSchema,
  ZodRemoveMemberMutationSchema,
} from "../schema";
import { Audit } from "@/server/audit";
import { type Prisma } from "@prisma/client";

export const removeMemberProcedure = withAuth
  .input(ZodRemoveMemberMutationSchema)
  .mutation(async (args) => {
    return await removeMemberHandler(args);
  });

interface removeMemberHandlerOptions {
  input: TypeZodRemoveMemberMutationSchema;
  ctx: withAuthTrpcContextType;
}

export async function removeMemberHandler({
  ctx: { db, session, requestIp, userAgent },
  input,
}: removeMemberHandlerOptions) {
  const user = session.user;
  const { memberId } = input;

  await db.$transaction(async (tx: Prisma.TransactionClient) => {
    const member = await tx.member.delete({
      where: {
        id: memberId,
        companyId: session.user.companyId,
      },
      select: {
        userId: true,
        user: {
          select: {
            name: true,
          },
        },
        company: {
          select: {
            name: true,
          },
        },
      },
    });

    await Audit.create(
      {
        action: "member.removed",
        companyId: user.companyId,
        actor: { type: "user", id: user.id },
        context: {
          requestIp,
          userAgent,
        },
        target: [{ type: "user", id: member.userId }],
        summary: `${user.name} removed ${member.user?.name} from ${member?.company?.name}`,
      },
      tx,
    );
  });

  return { success: true };
}

import { withAuth } from "@/trpc/api/trpc";
import { ZodRevokeInviteMutationSchema } from "../schema";
import { revokeExistingInviteTokens } from "@/server/member";
import { Audit } from "@/server/audit";
import { removeMemberHandler } from "./remove-member";

export const revokeInviteProcedure = withAuth
  .input(ZodRevokeInviteMutationSchema)
  .mutation(async ({ ctx, input }) => {
    const { db, session, requestIp, userAgent } = ctx;
    const user = session.user;
    const { memberId, email } = input;

    await db.$transaction(async (tx) => {
      await revokeExistingInviteTokens({ memberId, email, tx });

      const member = await tx.member.findFirst({
        where: {
          id: memberId,
        },
        select: {
          userId: true,
          user: {
            select: {
              name: true,
            },
          },
          company: {
            select: {
              name: true,
            },
          },
        },
      });

      await Audit.create({
        action: "member.revoked-invite",
        companyId: user.companyId,
        actor: { type: "user", id: user.id },
        context: {
          requestIp,
          userAgent,
        },
        target: [{ type: "user", id: member?.userId }],
        summary: `${user.name} revoked ${member?.user?.name} to join ${member?.company?.name}`,
      });
    });

    await removeMemberHandler({
      ctx,
      input: { memberId: input.memberId },
    });

    return { success: true };
  });

