    });

    it('should throw BadRequestException for invalid token', () => {
      vi.spyOn(storage.expireTokenEncryptor, 'decrypt').mockImplementationOnce(() => {
        throw new Error();
      });

      expect(() => storage.verifyReadToken('invalid-token')).toThrow(BadRequestException);
    });
  });
});

