        where: {
          email: input,
        },
      });
    }),

  addRegex: adminProcedure
    .input(
      z.object({
        regex: z.string().refine(...refineRegex),
        label: z.string().trim().min(1),
      })
    )
    .mutation(async ({ ctx, input }) => {
      await ctx.prisma.allowedEmailRegex.create({
