  setMutlipleAnswerMode: protectedProcedure
    .input(
      z.object({
        studySetId: z.string(),
        multipleAnswerMode: z.nativeEnum(MultipleAnswerMode),
      })
    )
    .mutation(async ({ ctx, input }) => {
      await ctx.prisma.studySetExperience.update({
