import {
  LimitedStudySetAnswerMode,
  type PrismaClient,
  type StudiableTerm,
  type Term,
} from "@prisma/client";
import { TRPCError } from "@trpc/server";
import slugify from "slugify";
import { z } from "zod";
import { USERNAME_REGEXP } from "../../../constants/characters";
import { MAX_DESC, MAX_TITLE } from "../common/constants";
import { shortId } from "../common/generator";
import { profanity } from "../common/profanity";
import { createTRPCRouter, protectedProcedure } from "../trpc";

export const getRecentFolders = async (
  prisma: PrismaClient,
  userId: string
) => {
  const recentExperiences = await prisma.folderExperience.findMany({
    where: {
      userId,
    },
    orderBy: {
      viewedAt: "desc",
    },
    take: 16,
  });
  const experienceIds = recentExperiences.map((e) => e.folderId);

  return (
    await prisma.folder.findMany({
      where: {
        id: {
          in: experienceIds,
        },
      },
      include: {
        user: true,
        _count: {
          select: {
            studySets: true,
          },
        },
      },
    })
  ).map((x) => ({
    ...x,
    viewedAt: recentExperiences.find((e) => e.folderId === x.id)!.viewedAt,
    user: {
      username: x.user.username,
      image: x.user.image,
    },
  }));
};

export const foldersRouter = createTRPCRouter({
  get: protectedProcedure
    .input(
      z.object({
        username: z.string().max(40).regex(USERNAME_REGEXP),
        idOrSlug: z.string(),
        includeTerms: z.boolean().optional(),
      })
    )
    .query(async ({ ctx, input }) => {
      const user = await ctx.prisma.user.findUnique({
        where: {
          username: input.username,
        },
      });

      if (!user) {
        throw new TRPCError({
          code: "NOT_FOUND",
        });
      }

      const folder = await ctx.prisma.folder.findFirst({
        where: {
          OR: [
            {
              userId: user.id,
              id: input.idOrSlug,
            },
            {
              userId: user.id,
              slug: input.idOrSlug,
            },
          ],
        },
        include: {
          studySets: {
            include: {
              studySet: {
                select: {
                  id: true,
                  title: true,
                  user: true,
                  visibility: true,
                  _count: {
                    select: {
                      terms: true,
                    },
                  },
                },
              },
            },
          },
        },
      });

      if (!folder) {
        throw new TRPCError({
          code: "NOT_FOUND",
        });
      }

      const isMyFolder = folder.userId === ctx.session.user.id;
      const studySets = folder.studySets.map((s) => s.studySet);
      const studySetsICanSee = studySets.filter((s) => {
        if (s.visibility === "Public") {
          return true;
        }
        if (s.visibility === "Unlisted") {
          // Prevent users from discovering unlisted study sets
          return s.user.id === ctx.session.user.id || isMyFolder;
        }
        if (s.visibility === "Private") {
          return s.user.id === ctx.session.user.id;
        }

        return false;
      });

      if (
        (!!studySets.length && !studySetsICanSee.length) ||
        (!studySets.length && !isMyFolder)
      ) {
        throw new TRPCError({
          code: "FORBIDDEN",
          message: "No study sets in this folder are visible to you",
        });
      }

      await ctx.prisma.folderExperience.upsert({
        where: {
          userId_folderId: {
            userId: ctx.session.user.id,
            folderId: folder.id,
          },
        },
        create: {
          folderId: folder.id,
          userId: ctx.session.user.id,
          viewedAt: new Date(),
        },
        update: {
          viewedAt: new Date(),
        },
      });

      const experience = await ctx.prisma.folderExperience.findUnique({
        where: {
          userId_folderId: {
            userId: ctx.session.user.id,
            folderId: folder.id,
          },
        },
        include: {
          studiableTerms: true,
        },
      });

      if (!experience) {
        throw new TRPCError({
          code: "INTERNAL_SERVER_ERROR",
        });
      }

      let terms = new Array<Term>();
      let starredTerms = new Array<string>();

      if (input.includeTerms) {
        const raw = await ctx.prisma.term.findMany({
          where: {
            studySetId: {
              in: studySetsICanSee.map((s) => s.id),
            },
          },
        });

        for (const set of studySetsICanSee) {
          terms = terms.concat(
            raw
              .filter((t) => t.studySetId === set.id)
              .sort((a, b) => a.rank - b.rank)
          );
        }
        terms = terms.map((x, i) => ({ ...x, rank: i }));

        starredTerms = (
          await ctx.prisma.starredTerm.findMany({
            where: {
              userId: ctx.session.user.id,
              termId: {
                in: terms.map((t) => t.id),
              },
            },
          })
        ).map((t) => t.termId);
      }

      if (!starredTerms.length) {
        await ctx.prisma.folderExperience.update({
          where: {
            userId_folderId: {
              userId: ctx.session.user.id,
              folderId: folder.id,
            },
          },
          data: {
            cardsStudyStarred: false,
          },
        });
        experience.cardsStudyStarred = false;
      }

      return {
        id: folder.id,
        title: folder.title,
        description: folder.description,
        user: {
          id: user.id,
          username: user.username,
          image: user.image,
          verified: user.verified,
        },
        sets: studySetsICanSee.map((s) => ({
          ...s,
          user: {
            id: s.user.id,
            username: s.user.username,
            image: s.user.image,
            verified: s.user.verified,
          },
        })),
        experience: {
          ...experience,
          starredTerms,
          studiableTerms: experience.studiableTerms.map((x: StudiableTerm) => ({
            id: x.termId,
            mode: x.mode,
            correctness: x.correctness,
            appearedInRound: x.appearedInRound,
            incorrectCount: x.incorrectCount,
          })),
        },
        terms,
        editableSets: studySetsICanSee
          .filter((s) => s.user.id === ctx.session.user.id)
          .map((s) => s.id),
      };
    }),

  recent: protectedProcedure.query(async ({ ctx }) => {
