function generateRandomString (length = 6, charset = BECH32_CHARSET) {
  const bytes = randomBytes(length)
  let result = ''

  // Even though we're creating biased numbers by mapping each byte to a bech32 character,
  // this is still secure because it provides 30 bits of security (32^6 = 2^30)
  // and we are limiting the number of attempts.
  for (let i = 0; i < length; i++) {
    result += charset[bytes[i] % charset.length]
  }

  return result
}

async function sendVerificationRequest ({
  identifier: email,
  url,
  token,
  provider
}, req) {
  let user = await prisma.user.findUnique({
    where: {
      // Look for the user by hashed email
      emailHash: hashEmail({ email })
    }
  })
  if (!user) {
    user = await prisma.user.findUnique({
      where: {
        // or plaintext email, in case a user tries to login via email during the migration
        // before their particular record has been migrated
        email
      }
    })
  }

  return new Promise((resolve, reject) => {
    const { server, from } = provider

    const site = new URL(url).host

    // if we're trying to sign in but no user was found, resolve the promise
    if (req.cookies.signin && !user) {
      return resolve()
    }

    nodemailer.createTransport(server).sendMail(
      {
        to: email,
        from,
        subject: `login to ${site}`,
        text: text({ url, token, site, email }),
        html: user ? html({ url, token, site, email }) : newUserHtml({ url, token, site, email })
      },
      (error) => {
        if (error) {
          return reject(new Error('SEND_VERIFICATION_EMAIL_ERROR', error))
        }
        return resolve()
      }
    )
  })
}

