/**
 * Used to check if a string is a valid URL
 * @param url The string to check
 * @returns Whether the string is a valid URL
 */
function isValidURL(url: string) {
  try {
    // Try to create a URL object
    // this will fail for endpoints like "localhost:3000", ie without a protocol
    new URL(url)
    return true
  } catch (error) {
    // Fallback to regular expression check
    const pattern = /^(https?:\/\/)?([\w.-]+)(\.[\w.-]+)+([/?].*)?$/
    return pattern.test(url)
  }
}

export class URLMenuService extends Service implements ContextMenu {
  public static readonly ID = "URL_CONTEXT_MENU_SERVICE"

  private t = getI18n()

  public readonly menuID = "url"

  private readonly contextMenu = this.bind(ContextMenuService)
  private readonly restTab = this.bind(RESTTabService)

  override onServiceInit() {
    this.contextMenu.registerMenu(this)
  }

  /**
   * Opens a new tab with the provided URL
   * @param url The URL to open
   */
  private openNewTab(url: string) {
    //create a new request object
    const request = {
      ...getDefaultRESTRequest(),
      endpoint: url,
    }

    this.restTab.createNewTab({
      type: "request",
      request: request,
      isDirty: false,
    })
  }

  getMenuFor(text: Readonly<string>): ContextMenuState {
    const results = ref<ContextMenuResult[]>([])

    if (isValidURL(text)) {
      results.value = [
        {
          id: "link-tab",
          text: {
            type: "text",
            text: this.t("context_menu.open_request_in_new_tab"),
          },
          icon: markRaw(IconCopyPlus),
          action: () => {
            this.openNewTab(text)
          },
        },
      ]
    }

    const resultObj = <ContextMenuState>{
      results: results.value,
    }

    return resultObj
  }
}

import { Service } from "dioc"
import { ref } from "vue"
import { parseString as setCookieParse } from "set-cookie-parser-es"

export type CookieDef = {
  name: string
  value: string
  domain: string
  path: string
  expires: string
}

export class CookieJarService extends Service {
  public static readonly ID = "COOKIE_JAR_SERVICE"

  /**
   * The cookie jar that stores all relevant cookie info.
   * The keys correspond to the domain of the cookie.
   * The cookie strings are stored as an array of strings corresponding to the domain
   */
  public cookieJar = ref(new Map<string, string[]>())

  public parseSetCookieString(setCookieString: string) {
    return setCookieParse(setCookieString)
  }

  public bulkApplyCookiesToDomain(cookies: string[], domain: string) {
    const existingDomainEntries = this.cookieJar.value.get(domain) ?? []
    existingDomainEntries.push(...cookies)

    this.cookieJar.value.set(domain, existingDomainEntries)
  }

  public getCookiesForURL(url: URL) {
    const relevantDomains = Array.from(this.cookieJar.value.keys()).filter(
      (domain) => url.hostname.endsWith(domain)
    )

    return relevantDomains
      .flatMap((domain) => {
        // Assemble the list of cookie entries from all the relevant domains

        const cookieStrings = this.cookieJar.value.get(domain)! // We know not nullable from how we filter above

        return cookieStrings.map((cookieString) =>
          this.parseSetCookieString(cookieString)
        )
      })
      .filter((cookie) => {
        // Perform the required checks on the cookies

        const passesPathCheck = url.pathname.startsWith(cookie.path ?? "/")

        const passesExpiresCheck = !cookie.expires
          ? true
          : cookie.expires.getTime() >= new Date().getTime()

        const passesSecureCheck = !cookie.secure
          ? true
          : url.protocol === "https:"

        return passesPathCheck && passesExpiresCheck && passesSecureCheck
      })
  }
}

import { Service } from "dioc"
import { cloneDeep } from "lodash-es"
import { reactive, computed } from "vue"

/**
 * Defines a environment variable.
 */
export type Variable = {
  key: string
  currentValue: string
  varIndex: number
  isSecret: boolean
}

/**
 * This service is used to store and manage current value of environment variables.
 * The current value are not synced with the server.
 * hence they are not persisted in the database. They are stored
 * in the local storage of the browser.
 */
export class CurrentValueService extends Service {
  public static readonly ID = "CURRENT_VALUE_SERVICE"

  /**
   * Map of current value of environments.
   * The key is the ID of the environment.
   * The value is the list of environment variables.
   */
  public environments = reactive(new Map<string, Variable[]>())

  /**
   * Add a new environment.
   * @param id ID of the environment
   * @param vars List of environment variables
   */
  public addEnvironment(id: string, vars: Variable[]) {
    this.environments.set(id, vars)
  }

  /**
   * Get a environment.
   * @param id ID of the environment
   */
  public getEnvironment(id: string) {
    return this.environments.get(id)
  }

  /**
   * Add a new environment variable to the environment.
   * If the environment does not exist, it will be created.
   * @param id ID of the environment
   * @param variable Environment variable to add
   */
  public addEnvironmentVariable(id: string, variable: Variable) {
    const vars = this.getEnvironment(id)
    if (vars) {
      const newVars = cloneDeep(vars)
      newVars.push(variable)
      this.environments.set(id, newVars)
    } else {
      this.environments.set(id, [variable])
    }
  }

  /**
   * Get a environment variable.
   * @param id ID of the environment
   * @param varIndex Index of the variable in the environment
   */
  public getEnvironmentVariable(id: string, varIndex: number) {
    const vars = this.getEnvironment(id)
    return vars?.find((v) => v.varIndex === varIndex)
  }

  /**
   * Used to get the value of a environment variable.
   * @param id ID of the environment
   * @param varIndex Index of the variable in the environment
   */
  public getEnvironmentVariableValue(id: string, varIndex: number) {
    const variable = this.getEnvironmentVariable(id, varIndex)
    return variable?.currentValue
  }

  /**
   *
   * @param environments Used to load environments from persisted state.
   */
  public loadEnvironmentsFromPersistedState(
    environments: Record<string, Variable[]>
  ) {
    if (environments) {
      this.environments.clear()

      Object.entries(environments).forEach(([id, vars]) => {
        this.addEnvironment(id, vars)
      })
    }
  }

  /**
   * Delete a environment.
   * @param id ID of the environment
   */
  public deleteEnvironment(id: string) {
    this.environments.delete(id)
  }

  /**
   * Delete a environment variable.
   * @param id ID of the environment
   * @param varIndex Index of the variable in the environment
   */
  public removeEnvironmentVariable(id: string, varIndex: number) {
    const vars = this.getEnvironment(id)
    const newVars = vars?.filter((v) => v.varIndex !== varIndex)
    this.environments.set(id, newVars || [])
  }

  /**
   * Used to update the ID of a environment.
   * Used while syncing with the server.
   * @param oldID old ID of the environment
   * @param newID new ID of the environment
   */
  public updateEnvironmentID(oldID: string, newID: string) {
    const vars = this.getEnvironment(oldID)
    this.environments.set(newID, vars || [])
    this.environments.delete(oldID)
  }

  /**
   *
   * @param id ID of the environment
   * @param key Key of the variable to check the value exists
   * @returns true if the key has a secret value
   */
  public hasValue(id: string, key: string) {
    return (
      this.environments.has(id) &&
      this.environments
        .get(id)!
        .some((v) => v.key === key && v.currentValue !== "")
    )
  }

  public getEnvironmentByKey(id: string, key: string) {
    const vars = this.getEnvironment(id)
    return vars?.find((v) => v.key === key)
  }

  /**
   * Used to update the value of a environment variable.
   */
  public persistableEnvironments = computed(() => {
    const environments: Record<string, Variable[]> = {}
    this.environments.forEach((vars, id) => {
      environments[id] = vars
    })
    return environments
  })
}

import { Service } from "dioc"

/**
 * This service provides debug utilities for the application and is
 * supposed to be used only in development.
 *
 * This service logs events from the container and also events
 * from all the services that are bound to the container. Along with that
 * this service exposes all registered services (including this) to global
 * scope (window) under the ID of the service so it can be accessed using
 * the console for debugging.
 *
 * This service injects couple of utilities into the global scope:
 *  - `_getService(id: string): Service | undefined` - Returns the service instance with the given ID or undefined.
 *  - `_getBoundServiceIDs(): string[]` - Returns the IDs of all the bound services.
 */
export class DebugService extends Service {
  public static readonly ID = "DEBUG_SERVICE"

  override onServiceInit() {
    console.debug("DebugService is initialized...")

    const container = this.getContainer()

    // Log container events
    container.getEventStream().subscribe((event) => {
      if (event.type === "SERVICE_BIND") {
        console.debug(
          "[CONTAINER] Service Bind:",
          event.bounderID ?? "<CONTAINER>",
          "->",
          event.boundeeID
        )
      } else if (event.type === "SERVICE_INIT") {
        console.debug("[CONTAINER] Service Init:", event.serviceID)

        // Subscribe to event stream of the newly initialized service
        const service = container.getBoundServiceWithID(event.serviceID)

        // Expose the service globally for debugging via a global variable
        ;(window as any)[event.serviceID] = service

        service?.getEventStream().subscribe((ev: any) => {
          console.debug(`[${event.serviceID}] Event:`, ev)
        })
      }
    })

    // Subscribe to event stream of all already bound services (if any)
    for (const [id, service] of container.getBoundServices()) {
      service.getEventStream().subscribe((event: any) => {
        console.debug(`[${id}]`, event)
      })

      // Expose the service globally for debugging via a global variable
      ;(window as any)[id] = service
    }

    // Inject debug utilities into the global scope
    ;(window as any)._getService = this.getService.bind(this)
    ;(window as any)._getBoundServiceIDs = this.getBoundServiceIDs.bind(this)
  }

  private getBoundServiceIDs() {
    return Array.from(this.getContainer().getBoundServices()).map(([id]) => id)
  }

  private getService(id: string) {
    return this.getContainer().getBoundServiceWithID(id)
  }
}

