import { GQLTabService } from "~/services/tab/graphql"
import { KernelInterceptorService } from "~/services/kernel-interceptor.service"

import { platform } from "~/platform"
import { NativeKernelInterceptorService } from "~/platform/std/kernel-interceptors/native"

import { performMigrations } from "~/helpers/migrations"
import { initBackendGQLClient } from "~/helpers/backend/GQLClient"
import { getKernelMode } from "@hoppscotch/kernel"

type InitEvent =
  | { type: "STORE_READY" }
  | { type: "PERSISTENCE_FIRST_READY" }
  | { type: "PERSISTENCE_LATER_READY" }
  | { type: "TABS_READY" }
  | { type: "NATIVE_KERNEL_NETWORKING_READY" }
  | { type: "AUTH_READY" }
  | { type: "BACKEND_CLIENT_READY" }
  | { type: "SYNC_READY" }
  | { type: "ALL_READY" }

/**
 * Service responsible for coordinating the initialization sequence.
 */
export class InitializationService extends Service<InitEvent> {
  public static readonly ID = "INITIALIZATION_SERVICE"

  private initState = {
    store: false,
    persistenceFirst: false,
    tabs: false,
    nativeKernelNetworking: false,
    auth: false,
    sync: false,
    persistenceLater: false,
    backendClient: false,
  }

  private async initStore() {
    const persistenceService = getService(PersistenceService)
    const result = await persistenceService.init()

    if (E.isLeft(result)) {
      throw new Error(`Store initialization failed: ${result.left.message}`)
    }

    this.initState.store = true
    this.emit({ type: "STORE_READY" })
  }

  private async initPersistenceFirst() {
    if (!this.initState.store) {
      throw new Error("Cannot initialize persistence before store")
    }

    const persistenceService = getService(PersistenceService)
    await persistenceService.setupFirst()

    this.initState.persistenceFirst = true
    this.emit({ type: "PERSISTENCE_FIRST_READY" })
  }

  private async initTabs() {
    if (!this.initState.persistenceFirst) {
      throw new Error("Cannot initialize tabs before persistence")
    }

    const restTabService = getService(RESTTabService)
    const gqlTabService = getService(GQLTabService)

    await Promise.all([restTabService.init(), gqlTabService.init()])

    this.initState.tabs = true
    this.emit({ type: "TABS_READY" })
  }

  private async initNativeKernelNetworking() {
    const interceptorService = getService(KernelInterceptorService)
    const nativeInterceptorService = getService(NativeKernelInterceptorService)
    interceptorService.register(nativeInterceptorService)
    interceptorService.setActive("native")

    this.initState.nativeKernelNetworking = true
    this.emit({ type: "NATIVE_KERNEL_NETWORKING_READY" })
  }

  private async initAuth() {
    if (
      getKernelMode() === "desktop" &&
      !this.initState.nativeKernelNetworking
    ) {
      throw new Error(
        "Cannot initialize auth on desktop before native networking"
      )
    }

    if (!this.initState.persistenceFirst || !this.initState.tabs) {
      throw new Error("Cannot initialize auth before persistence and tabs")
    }

    await platform.auth.performAuthInit()

    this.initState.auth = true
    this.emit({ type: "AUTH_READY" })
  }

  private async initBackendClient() {
    initBackendGQLClient()

    this.initState.backendClient = true
    this.emit({ type: "BACKEND_CLIENT_READY" })
  }

  private async initPersistenceLater() {
    if (!this.initState.persistenceFirst) {
      throw new Error("Cannot initialize persistence before store")
    }

    const persistenceService = getService(PersistenceService)
    await persistenceService.setupLater()

    this.initState.persistenceLater = true
    this.emit({ type: "PERSISTENCE_LATER_READY" })
  }

  private async initSync() {
    if (!this.initState.auth) {
      throw new Error("Cannot initialize remaining services before auth")
    }

    await Promise.all([
      platform.sync.settings.initSettingsSync(),
      platform.sync.collections.initCollectionsSync(),
      platform.sync.history.initHistorySync(),
      platform.sync.environments.initEnvironmentsSync(),
      platform.analytics?.initAnalytics(),
    ])

    this.emit({ type: "SYNC_READY" })
  }

  public async initPre() {
    await this.initStore()
    await this.initPersistenceFirst()

    if (getKernelMode() === "desktop") {
      await this.initNativeKernelNetworking()
    }

    await this.initBackendClient()
    await this.initTabs()
  }

  public async initAuthAndSync() {
    await this.initAuth()
    await this.initSync()
  }

  public async initPost() {
    await this.initPersistenceLater()
    performMigrations()
  }

  public isInitialized() {
    return Object.values(this.initState).every(Boolean)
  }
}

import {
  HoppRESTRequest,
  HoppRESTResponseOriginalRequest,
} from "@hoppscotch/data"
import { refDebounced } from "@vueuse/core"
import { Service } from "dioc"
import { computed, markRaw, reactive } from "vue"
import { Component, Ref, ref, watch } from "vue"
import { HoppRESTResponse } from "~/helpers/types/HoppRESTResponse"
import { RESTTabService } from "../tab/rest"
/**
 * Defines how to render the text in an Inspector Result
 */
export type InspectorTextType<T extends object | Component = never> =
  | {
      type: "text"
      text: string[] | string
    }
  | {
      type: "custom"
      component: T
      componentProps: T extends Component<infer Props> ? Props : never
    }

export type InspectorLocation =
  | {
      type: "url"
    }
  | {
      type: "header"
      position: "key" | "value"
      key?: string
      index?: number
    }
  | {
      type: "parameter"
      position: "key" | "value"
      key?: string
      index?: number
    }
  | {
      type: "body"
      key: string
      index: number
    }
  | {
      type: "response"
    }
  | {
      type: "body-content-type-header"
    }

/**
 * Defines info about an inspector result so the UI can render it
 */
export interface InspectorResult {
  id: string
  text: InspectorTextType<any>
  icon: object | Component
  severity: number
  isApplicable: boolean
  action?: {
    text: string
    apply: () => void
  }
  doc?: {
    text: string
    link: string
  }
  locations: InspectorLocation
}

/**
 * Defines the state of the inspector service
 */
export type InspectorState = {
  results: InspectorResult[]
}

/**
 * Defines an inspector that can be registered with the inspector service
 * Inspectors are used to perform checks on a request and return the results
 */
export interface Inspector {
  /**
   * The unique ID of the inspector
   */
  inspectorID: string
  /**
   * Returns the inspector results for the request.
   * NOTE: The refs passed down are readonly and are debounced to avoid performance issues
   * @param req The ref to the request to inspect
   * @param res The ref to the response to inspect
   * @returns The ref to the inspector results
   */
  getInspections: (
    req: Readonly<Ref<HoppRESTRequest | HoppRESTResponseOriginalRequest>>,
    res: Readonly<Ref<HoppRESTResponse | null | undefined>>
  ) => Ref<InspectorResult[]>
}

/**
 * Defines the inspection service
 * The service watches the current active tab and returns the inspector results for the request and response
 */
export class InspectionService extends Service {
  public static readonly ID = "INSPECTION_SERVICE"

  private inspectors: Map<string, Inspector> = reactive(new Map())

  private tabs: Ref<Map<string, InspectorResult[]>> = ref(new Map())

  private readonly restTab = this.bind(RESTTabService)

  override onServiceInit() {
    this.initializeListeners()
  }

  /**
   * Registers a inspector with the inspection service
   * @param inspector The inspector instance to register
   */
  public registerInspector(inspector: Inspector) {
    // markRaw is required here so that the inspector is not made reactive
    this.inspectors.set(inspector.inspectorID, markRaw(inspector))
  }

  private initializeListeners() {
    watch(
      () => [this.inspectors.entries(), this.restTab.currentActiveTab.value.id],
      () => {
        const currentTabRequest = computed(() => {
          if (
            this.restTab.currentActiveTab.value.document.type === "test-runner"
          )
            return null

          return this.restTab.currentActiveTab.value.document.type === "request"
            ? this.restTab.currentActiveTab.value.document.request
            : this.restTab.currentActiveTab.value.document.response
                .originalRequest
        })

        const currentTabResponse = computed(() => {
          if (this.restTab.currentActiveTab.value.document.type === "request") {
            return this.restTab.currentActiveTab.value.document.response
          }
          return null
        })

        const reqRef = computed(() => currentTabRequest.value)
        const resRef = computed(() => currentTabResponse.value)

        const debouncedReq = refDebounced(reqRef, 1000, { maxWait: 2000 })
        const debouncedRes = refDebounced(resRef, 1000, { maxWait: 2000 })

        const inspectorRefs = Array.from(this.inspectors.values()).map((x) =>
          // @ts-expect-error - This is a valid call
          x.getInspections(debouncedReq, debouncedRes)
        )

        const activeInspections = computed(() =>
          inspectorRefs.flatMap((x) => x!.value)
        )

        watch(
          () => [...inspectorRefs.flatMap((x) => x!.value)],
          () => {
            this.tabs.value.set(
              this.restTab.currentActiveTab.value.id,
              activeInspections.value
            )
          },
          { immediate: true }
        )
      },
      { immediate: true, flush: "pre" }
    )
  }

  public deleteTabInspectorResult(tabID: string) {
    // TODO: Move Tabs into a service and implement this with an event instead
    this.tabs.value.delete(tabID)
  }

  /**
   * Returns a reactive view into the inspector results for a specific tab
   * @param tabID The ID of the tab to get the results for
   * @param filter The filter to apply to the results.
   * @returns The ref into the inspector results, if the tab doesn't exist, a ref into an empty array is returned
   */
  public getResultViewFor(
    tabID: string,
    filter: (x: InspectorResult) => boolean = () => true
  ) {
    return computed(() => this.tabs.value.get(tabID)?.filter(filter) ?? [])
  }
}

import { getI18n } from "~/modules/i18n"
import {
  InspectionService,
  Inspector,
  InspectorLocation,
  InspectorResult,
} from ".."
import { Service } from "dioc"
import { Ref, markRaw } from "vue"
import IconPlusCircle from "~icons/lucide/plus-circle"
import {
  HoppRESTRequest,
  HoppRESTResponseOriginalRequest,
} from "@hoppscotch/data"
import {
  AggregateEnvironment,
  aggregateEnvsWithCurrentValue$,
  getCurrentEnvironment,
  getSelectedEnvironmentType,
} from "~/newstore/environments"
import { invokeAction } from "~/helpers/actions"
import { computed } from "vue"
import { useStreamStatic } from "~/composables/stream"
import { SecretEnvironmentService } from "~/services/secret-environment.service"
import { RESTTabService } from "~/services/tab/rest"
import { CurrentValueService } from "~/services/current-environment-value.service"

const HOPP_ENVIRONMENT_REGEX = /(<<[a-zA-Z0-9-_]+>>)/g

const isENVInString = (str: string) => {
  return HOPP_ENVIRONMENT_REGEX.test(str)
}

/**
 * This inspector is responsible for inspecting the environment variables of a input.
 * It checks if the environment variables are defined in the environment.
 * It also provides an action to add the environment variable.
 *
 * NOTE: Initializing this service registers it as a inspector with the Inspection Service.
 */
export class EnvironmentInspectorService extends Service implements Inspector {
  public static readonly ID = "ENVIRONMENT_INSPECTOR_SERVICE"

  private t = getI18n()

  public readonly inspectorID = "environment"

  private readonly inspection = this.bind(InspectionService)
  private readonly secretEnvs = this.bind(SecretEnvironmentService)
  private readonly currentEnvs = this.bind(CurrentValueService)
  private readonly restTabs = this.bind(RESTTabService)

  private aggregateEnvsWithValue = useStreamStatic(
    aggregateEnvsWithCurrentValue$,
    [],
    () => {
      /* noop */
    }
  )[0]

  override onServiceInit() {
    this.inspection.registerInspector(this)
  }

  /**
   * Validates the environment variables in the target array
   * @param target The target array to validate
   * @param locations The location where results are to be displayed
   * @returns The results array containing the results of the validation
   */
  private validateEnvironmentVariables = (
    target: any[],
    locations: InspectorLocation
  ) => {
    const newErrors: InspectorResult[] = []

    const currentTab = this.restTabs.currentActiveTab.value

    const currentTabRequest =
      currentTab.document.type === "request"
        ? currentTab.document.request
        : currentTab.document.type === "example-response"
          ? currentTab.document.response.originalRequest
          : null

    const environmentVariables = [
      ...(currentTabRequest?.requestVariables ?? []),
      ...this.aggregateEnvsWithValue.value,
    ]

    const envKeys = environmentVariables.map((e) => e.key)

    target.forEach((element, index) => {
      if (isENVInString(element)) {
        const extractedEnv = element.match(HOPP_ENVIRONMENT_REGEX)

        if (extractedEnv) {
          extractedEnv.forEach((exEnv: string) => {
            const formattedExEnv = exEnv.slice(2, -2)
            const itemLocation: InspectorLocation = {
              type: locations.type,
              position:
                locations.type === "url" ||
                locations.type === "body" ||
                locations.type === "response" ||
                locations.type === "body-content-type-header"
                  ? "key"
                  : locations.position,
              index: index,
              key: element,
            }
            if (!envKeys.includes(formattedExEnv)) {
              newErrors.push({
                id: `environment-not-found-${newErrors.length}`,
                text: {
                  type: "text",
                  text: this.t("inspections.environment.not_found", {
                    environment: exEnv,
                  }),
                },
                icon: markRaw(IconPlusCircle),
                action: {
                  text: this.t("inspections.environment.add_environment"),
                  apply: () => {
                    invokeAction("modals.environment.add", {
                      envName: formattedExEnv,
                      variableName: "",
                    })
                  },
                },
                severity: 3,
                isApplicable: true,
                locations: itemLocation,
                doc: {
                  text: this.t("action.learn_more"),
                  link: "https://docs.hoppscotch.io/documentation/features/inspections",
                },
              })
            }
          })
        }
      }
    })

    return newErrors
  }

  /**
   * Transforms the environment list to a list with unique keys with value
   * @param envs The environment list to be transformed
   * @returns The transformed environment list with keys with value
   */
  private filterNonEmptyEnvironmentVariables = (
    envs: AggregateEnvironment[]
  ): AggregateEnvironment[] => {
    const envsMap = new Map<string, AggregateEnvironment>()

    envs.forEach((env) => {
      if (envsMap.has(env.key)) {
        const existingEnv = envsMap.get(env.key)

        if (existingEnv?.currentValue === "" && env.currentValue !== "") {
          envsMap.set(env.key, env)
        }
      } else {
        envsMap.set(env.key, env)
      }
    })

    return Array.from(envsMap.values())
  }

  /**
   * Checks if the environment variables in the target have empty current value or initial value.
   * @param target The target array to validate
   * @param locations The location where results are to be displayed
   * @returns The results array containing the results of the validation
   */
  private validateEmptyEnvironmentVariables = (
    target: any[],
    locations: InspectorLocation
  ) => {
    const newErrors: InspectorResult[] = []

    target.forEach((element, index) => {
      if (isENVInString(element)) {
        const extractedEnv = element.match(HOPP_ENVIRONMENT_REGEX)

        if (extractedEnv) {
          extractedEnv.forEach((exEnv: string) => {
            const formattedExEnv = exEnv.slice(2, -2)
            const currentSelectedEnvironment = getCurrentEnvironment()

            const currentTab = this.restTabs.currentActiveTab.value

            const currentTabRequest =
              currentTab.document.type === "request"
                ? currentTab.document.request
                : currentTab.document.type === "example-response"
                  ? currentTab.document.response.originalRequest
                  : null

            const environmentVariables =
              this.filterNonEmptyEnvironmentVariables([
                // Transform the request variables to environment variables
                ...(currentTabRequest?.requestVariables ?? []).map((env) => ({
                  key: env.key,
                  currentValue: env.value,
                  initialValue: env.value,
                  secret: false,
                  sourceEnv: "RequestVariable",
                })),
                ...this.aggregateEnvsWithValue.value,
              ])

            environmentVariables.forEach((env) => {
              const hasSecretEnv = this.secretEnvs.hasSecretValue(
                env.sourceEnv !== "Global"
                  ? currentSelectedEnvironment.id
                  : "Global",
                env.key
              )

              const hasValue =
                this.currentEnvs.hasValue(
                  env.sourceEnv !== "Global"
                    ? currentSelectedEnvironment.id
                    : "Global",
                  env.key
                ) ||
                env.currentValue !== "" ||
                env.initialValue !== ""

              if (env.key === formattedExEnv) {
                if (env.secret ? !hasSecretEnv : !hasValue) {
                  const itemLocation: InspectorLocation = {
                    type: locations.type,
                    position:
                      locations.type === "url" ||
                      locations.type === "body" ||
                      locations.type === "response" ||
                      locations.type === "body-content-type-header"
                        ? "key"
                        : locations.position,
                    index: index,
                    key: element,
                  }

                  const currentEnvironmentType = getSelectedEnvironmentType()

                  let invokeActionType:
                    | "modals.my.environment.edit"
                    | "modals.team.environment.edit"
                    | "modals.global.environment.update" =
                    "modals.my.environment.edit"

                  if (env.sourceEnv === "Global") {
                    invokeActionType = "modals.global.environment.update"
                  } else if (currentEnvironmentType === "MY_ENV") {
                    invokeActionType = "modals.my.environment.edit"
                  } else if (currentEnvironmentType === "TEAM_ENV") {
                    invokeActionType = "modals.team.environment.edit"
                  } else {
                    invokeActionType = "modals.my.environment.edit"
                  }

                  newErrors.push({
                    id: `environment-empty-${newErrors.length}`,
                    text: {
                      type: "text",
                      text: this.t("inspections.environment.empty_value", {
                        variable: exEnv,
                      }),
                    },
                    icon: markRaw(IconPlusCircle),
                    action: {
                      text: this.t(
                        "inspections.environment.add_environment_value"
                      ),
                      apply: () => {
                        if (
                          env.sourceEnv === "RequestVariable" &&
                          currentTab.document.type === "request"
                        ) {
                          currentTab.document.optionTabPreference =
                            "requestVariables"
                        } else {
                          invokeAction(invokeActionType, {
                            envName:
                              env.sourceEnv === "Global"
                                ? "Global"
                                : currentSelectedEnvironment.name,
                            variableName: formattedExEnv,
                            isSecret: env.secret,
                          })
                        }
                      },
                    },
                    severity: 2,
                    isApplicable: true,
                    locations: itemLocation,
                    doc: {
                      text: this.t("action.learn_more"),
                      link: "https://docs.hoppscotch.io/documentation/features/inspections",
                    },
                  })
                }
              }
            })
          })
        }
      }
    })

    return newErrors
  }

  getInspections(
    req: Readonly<Ref<HoppRESTRequest | HoppRESTResponseOriginalRequest>>
  ) {
    return computed(() => {
      const results: InspectorResult[] = []

      if (!req.value) return results

      const headers = req.value.headers

      const params = req.value.params

      /**
       * Validate the environment variables in the URL
       */
      const url = req.value.endpoint

      results.push(
        ...this.validateEnvironmentVariables([url], {
          type: "url",
        })
      )
      results.push(
        ...this.validateEmptyEnvironmentVariables([url], {
          type: "url",
        })
      )

      /**
       * Validate the environment variables in the headers
       */
      const headerKeys = Object.values(headers).map((header) => header.key)

      results.push(
        ...this.validateEnvironmentVariables(headerKeys, {
          type: "header",
          position: "key",
        })
      )
      results.push(
        ...this.validateEmptyEnvironmentVariables(headerKeys, {
          type: "header",
          position: "key",
        })
      )

      const headerValues = Object.values(headers).map((header) => header.value)

      results.push(
        ...this.validateEnvironmentVariables(headerValues, {
          type: "header",
          position: "value",
        })
      )
      results.push(
        ...this.validateEmptyEnvironmentVariables(headerValues, {
          type: "header",
          position: "value",
        })
      )

      /**
       * Validate the environment variables in the parameters
       */
      const paramsKeys = Object.values(params).map((param) => param.key)

      results.push(
        ...this.validateEnvironmentVariables(paramsKeys, {
          type: "parameter",
          position: "key",
        })
      )
      results.push(
        ...this.validateEmptyEnvironmentVariables(paramsKeys, {
          type: "parameter",
          position: "key",
        })
      )

      const paramsValues = Object.values(params).map((param) => param.value)

      results.push(
        ...this.validateEnvironmentVariables(paramsValues, {
          type: "parameter",
          position: "value",
        })
      )

      results.push(
        ...this.validateEmptyEnvironmentVariables(paramsValues, {
          type: "parameter",
          position: "value",
        })
      )

      return results
    })
  }
}

import { Service } from "dioc"
import { InspectionService, Inspector, InspectorResult } from ".."
import { computed, markRaw, Ref } from "vue"
import {
  HoppRESTRequest,
  HoppRESTResponseOriginalRequest,
} from "@hoppscotch/data"
import IconAlertTriangle from "~icons/lucide/alert-triangle"
import { getI18n } from "~/modules/i18n"
import { KernelInterceptorService } from "~/services/kernel-interceptor.service"
import { RelayCapabilities } from "@hoppscotch/kernel"

type CapabilityRequirement<K extends keyof RelayCapabilities> = {
  type: K
  name: string & RelayCapabilities[K] extends Set<infer T> ? T : never
}

interface InspectionMatch {
  index?: number
  key?: string
}

interface CapabilityCheck {
  matcher: (
    req: HoppRESTRequest | HoppRESTResponseOriginalRequest
  ) => InspectionMatch | null
  requires: CapabilityRequirement<keyof RelayCapabilities>
  createInspection: (match: InspectionMatch) => InspectorResult
}

export class RequestInspectorService extends Service implements Inspector {
  public static readonly ID = "REQUEST_INSPECTOR_SERVICE"
  public readonly inspectorID = "request"

  private readonly t = getI18n()
  private readonly inspection = this.bind(InspectionService)
  private readonly kernelInterceptor = this.bind(KernelInterceptorService)

  private readonly inspectionChecks: CapabilityCheck[] = [
    {
      matcher: (req) => {
        const localHostURLs = ["localhost", "127.0.0.1"]
        return localHostURLs.some((host) => req.endpoint.includes(host))
          ? {}
          : null
      },
      requires: {
        type: "advanced",
        name: "localaccess",
      },
      createInspection: () => ({
        id: "localaccess",
        icon: markRaw(IconAlertTriangle),
        text: {
          type: "text",
          text: this.t("inspections.url.localaccess_unsupported"),
        },
        severity: 2,
        isApplicable: true,
        locations: { type: "url" },
      }),
    },
    {
      matcher: (req) => (req.auth.authType === "digest" ? {} : null),
      requires: { type: "auth", name: "digest" },
      createInspection: () => ({
        id: "digest-auth",
        icon: markRaw(IconAlertTriangle),
        text: { type: "text", text: this.t("inspections.auth.digest") },
        severity: 2,
        isApplicable: true,
        locations: { type: "url" },
        doc: {
          text: this.t("action.learn_more"),
          link: "https://docs.hoppscotch.io/documentation/features/inspections",
        },
      }),
    },
    {
      matcher: (req) => (req.auth.authType === "hawk" ? {} : null),
      requires: { type: "auth", name: "hawk" },
      createInspection: () => ({
        id: "hawk-auth",
        icon: markRaw(IconAlertTriangle),
        text: { type: "text", text: this.t("inspections.auth.hawk") },
        severity: 2,
        isApplicable: true,
        locations: { type: "url" },
        doc: {
          text: this.t("action.learn_more"),
          link: "https://docs.hoppscotch.io/documentation/features/inspections",
        },
      }),
    },
    {
      matcher: (req) => {
        const index = req.headers.findIndex((h) =>
          h.key.toLowerCase().includes("cookie")
        )
        return index !== -1 ? { index, key: req.headers[index].key } : null
      },
      requires: { type: "advanced", name: "cookies" },
      createInspection: (match) => ({
        id: "cookie-header",
        icon: markRaw(IconAlertTriangle),
        text: { type: "text", text: this.t("inspections.header.cookie") },
        severity: 2,
        isApplicable: true,
        locations: {
          type: "header",
          position: "key",
          ...match,
        },
        doc: {
          text: this.t("action.learn_more"),
          link: "https://hoppscotch.com/download",
        },
      }),
    },
    {
      matcher: (req) =>
        req.body.contentType === "application/octet-stream" ? {} : null,
      requires: { type: "content", name: "binary" },
      createInspection: () => ({
        id: "binary-body",
        icon: markRaw(IconAlertTriangle),
        text: { type: "text", text: this.t("inspections.body.binary") },
        severity: 2,
        isApplicable: true,
        locations: { type: "body-content-type-header" },
        doc: {
          text: this.t("action.learn_more"),
          link: "https://docs.hoppscotch.io/documentation/features/inspections",
        },
      }),
    },
  ]

  override onServiceInit() {
    this.inspection.registerInspector(this)
  }

  private validateCapability(
    req: HoppRESTRequest | HoppRESTResponseOriginalRequest,
    { matcher, requires, createInspection }: CapabilityCheck
  ): InspectorResult[] {
    const match = matcher(req)
    if (!match) return []

    const capabilities = this.kernelInterceptor.current.value?.capabilities
    const supports = capabilities[requires.type].has(requires.name)

    return !supports ? [createInspection(match)] : []
  }

  getInspections(
    req: Readonly<Ref<HoppRESTRequest | HoppRESTResponseOriginalRequest>>
  ) {
    return computed(() =>
      !req.value
        ? []
        : this.inspectionChecks.flatMap((check) =>
            this.validateCapability(req.value, check)
          )
    )
  }
}

import { Service } from "dioc"
import { InspectionService, Inspector, InspectorResult } from ".."
import { getI18n } from "~/modules/i18n"
import {
  HoppRESTRequest,
  HoppRESTResponseOriginalRequest,
} from "@hoppscotch/data"
import { markRaw } from "vue"
import IconAlertTriangle from "~icons/lucide/alert-triangle"
import { HoppRESTResponse } from "~/helpers/types/HoppRESTResponse"
import { Ref } from "vue"
import { computed } from "vue"

/**
 * This inspector is responsible for inspecting the response of a request.
 * It checks if the response is successful and if it contains errors.
 *
 * NOTE: Initializing this service registers it as a inspector with the Inspection Service.
 */
export class ResponseInspectorService extends Service implements Inspector {
  public static readonly ID = "RESPONSE_INSPECTOR_SERVICE"

  private t = getI18n()

  public readonly inspectorID = "response"

  private readonly inspection = this.bind(InspectionService)

  override onServiceInit() {
    this.inspection.registerInspector(this)
  }

  getInspections(
    _req: Readonly<Ref<HoppRESTRequest | HoppRESTResponseOriginalRequest>>,
    res: Readonly<Ref<HoppRESTResponse | null | undefined>>
  ) {
    return computed(() => {
      const results: InspectorResult[] = []
      if (!res.value) return results

      const hasErrors =
        res && (res.value.type !== "success" || res.value.statusCode !== 200)

      let text: string | undefined = undefined

      if (res.value.type === "network_fail" && !navigator.onLine) {
        text = this.t("inspections.response.network_error")
      } else if (res.value.type === "fail") {
        text = this.t("inspections.response.default_error")
      } else if (res.value.type === "success" && res.value.statusCode === 404) {
        text = this.t("inspections.response.404_error")
      } else if (res.value.type === "success" && res.value.statusCode === 401) {
        text = this.t("inspections.response.401_error")
      }

      if (hasErrors && text) {
        results.push({
          id: "url",
          icon: markRaw(IconAlertTriangle),
          text: {
            type: "text",
            text: text,
          },
          severity: 2,
          isApplicable: true,
          locations: {
            type: "response",
          },
          doc: {
            text: this.t("action.learn_more"),
            link: "https://docs.hoppscotch.io/documentation/features/inspections",
          },
        })
      }

      return results
    })
  }
}

import { Service } from "dioc"
import { BehaviorSubject, Observable } from "rxjs"
import { computed } from "vue"
import { LazyStore } from "@tauri-apps/plugin-store"
import { download, load, clear, remove } from "@hoppscotch/plugin-appload"
import { useToast } from "~/composables/toast"
import { platform } from "~/platform"

const STORE_PATH = "hopp.store.json"
const MAX_RECENT_INSTANCES = 10

type ServerInstance = {
  type: "server"
  serverUrl: string
  displayName: string
  version: string
  lastUsed: string
  bundleName?: string
}

type VendoredInstance = {
  type: "vendored"
  displayName: string
  version: string
}

export type InstanceType = ServerInstance | VendoredInstance

export type ConnectionState =
  | { status: "idle" }
  | { status: "connecting"; target: string }
  | { status: "connected"; instance: InstanceType }
  | { status: "error"; target: string; message: string }

export class InstanceSwitcherService extends Service<ConnectionState> {
  public static readonly ID = "INSTANCE_SWITCHER_SERVICE"

  private state$ = new BehaviorSubject<ConnectionState>({ status: "idle" })
  private recentInstances$ = new BehaviorSubject<ServerInstance[]>([])
  private store!: LazyStore
  private toast = useToast()

  public getVendoredInstance(): VendoredInstance {
    const { instanceType, displayConfig } = platform.instance
    const { displayName, version } = displayConfig

    return {
      type: instanceType,
      displayName,
      version,
    }
  }

  override async onServiceInit(): Promise<void> {
    this.store = new LazyStore(STORE_PATH)
    await this.store.init()
    await this.loadRecentInstances()

    if (this.inVendoredEnvironment()) {
      this.state$.next({
        status: "connected",
        instance: this.getVendoredInstance(),
      })
      this.emit(this.state$.value)
    } else {
      await this.loadSavedState()
    }
  }

  private inVendoredEnvironment(): boolean {
    try {
      return (
        window.location.hostname === "hoppscotch" &&
        window.location.protocol === "app:"
      )
    } catch {
      return false
    }
  }

  public getStateStream(): Observable<ConnectionState> {
    return this.state$
  }

  public getRecentInstancesStream(): Observable<ServerInstance[]> {
    return this.recentInstances$
  }

  public getCurrentState() {
    return computed(() => this.state$.value)
  }

  public getCurrentInstance() {
    return computed(() => {
      const state = this.state$.value
      return state.status === "connected" ? state.instance : null
    })
  }

  public getRecentInstances() {
    return computed(() => this.recentInstances$.value)
  }

  public isConnecting() {
    return computed(() => this.state$.value.status === "connecting")
  }

  public getConnectionError() {
    return computed(() => {
      const state = this.state$.value
      return state.status === "error" ? state.message : null
    })
  }

  public async connectToVendoredInstance(): Promise<boolean> {
    if (this.isCurrentlyVendored()) {
      return true
    }

    this.state$.next({
      status: "connecting",
      target: this.getVendoredInstance().displayName,
    })
    this.emit(this.state$.value)

    try {
      this.state$.next({
        status: "connected",
        instance: this.getVendoredInstance(),
      })
      this.emit(this.state$.value)

      await this.saveCurrentState()

      this.toast.success(
        platform.instance.displayConfig.connectingMessage.replace(
          "{instanceName}",
          this.getVendoredInstance().displayName
        )
      )

      const loadResponse = await load({
        bundleName: "Hoppscotch",
        window: { title: "Hoppscotch" },
      })

      if (!loadResponse.success) {
        throw new Error(
          `Failed to load ${this.getVendoredInstance().type} bundle`
        )
      }

      this.toast.success(
        platform.instance.displayConfig.connectedMessage.replace(
          "{instanceName}",
          this.getVendoredInstance().displayName
        )
      )
      return true
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error)
      this.state$.next({
        status: "error",
        target: this.getVendoredInstance().displayName,
        message: errorMessage,
      })
      this.emit(this.state$.value)

      this.toast.error(`Failed to connect: ${errorMessage}`)
      return false
    }
  }

  public async connectToServerInstance(serverUrl: string): Promise<boolean> {
    if (this.isCurrentlyConnectedTo(serverUrl)) {
      const currentState = this.state$.value
      if (
        currentState.status === "connected" &&
        currentState.instance.type === "server"
      ) {
        const updatedInstance: ServerInstance = {
          ...currentState.instance,
          lastUsed: new Date().toISOString(),
        }

        await this.updateRecentInstance(updatedInstance)
      }
      return true
    }

    const normalizedUrl = this.normalizeUrl(serverUrl)
    const displayName = this.getDisplayNameFromUrl(normalizedUrl)

    this.state$.next({
      status: "connecting",
      target: displayName,
    })
    this.emit(this.state$.value)

    try {
      const downloadResponse = await download({ serverUrl: normalizedUrl })
      if (!downloadResponse.success) {
        throw new Error("Failed to download bundle")
      }

      const instance: ServerInstance = {
        type: "server",
        serverUrl: normalizedUrl,
        displayName,
        version: downloadResponse.version,
        lastUsed: new Date().toISOString(),
        bundleName: downloadResponse.bundleName,
      }

      await this.updateRecentInstance(instance)

      this.state$.next({
        status: "connected",
        instance,
      })
      this.emit(this.state$.value)

      await this.saveCurrentState()

      this.toast.success(`Connecting to ${displayName}`)

      const loadResponse = await load({
        bundleName: downloadResponse.bundleName,
        window: { title: "Hoppscotch" },
      })

      if (!loadResponse.success) {
        throw new Error("Failed to load bundle")
      }

      this.toast.success(`Connected to ${displayName}`)
      return true
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error)
      this.state$.next({
        status: "error",
        target: displayName,
        message: errorMessage,
      })
      this.emit(this.state$.value)

      this.toast.error(`Connection failed: ${errorMessage}`)
      return false
    }
  }

  public async removeInstance(serverUrl: string): Promise<boolean> {
    try {
      const normalizedUrl = this.normalizeUrl(serverUrl)

      const instanceToRemove = this.recentInstances$.value.find(
        (instance) => instance.serverUrl === normalizedUrl
      )

      if (!instanceToRemove) {
        return false
      }

      if (instanceToRemove.bundleName) {
        try {
          await remove({
            bundleName: instanceToRemove.bundleName,
            serverUrl: normalizedUrl,
          })
        } catch (error) {
          console.error("Failed to remove bundle from storage:", error)
          // Continue with instance removal even if bundle removal fails
        }
      }

      const instances = this.recentInstances$.value.filter(
        (instance) => instance.serverUrl !== normalizedUrl
      )

      this.recentInstances$.next(instances)
      await this.saveRecentInstances()

      const displayName = this.getDisplayNameFromUrl(serverUrl)
      this.toast.success(`Removed ${displayName}`)

      // If we're currently connected to this instance, go back to idle state
      if (this.isCurrentlyConnectedTo(serverUrl)) {
        this.state$.next({ status: "idle" })
        this.emit(this.state$.value)
        await this.saveCurrentState()
      }

      return true
    } catch (error) {
      this.toast.error("Failed to remove instance")
      return false
    }
  }

  public async clearCache(): Promise<boolean> {
    try {
      await clear()
      this.toast.success("Cache cleared successfully")
      return true
    } catch (error) {
      this.toast.error("Failed to clear cache")
      return false
    }
  }

  public getCurrentInstanceDisplayName(): string {
    const state = this.state$.value
    if (state.status !== "connected") {
      return "Hoppscotch"
    }
    return state.instance.displayName
  }

  public getDisplayNameFromUrl(url: string): string {
    try {
      const urlObj = new URL(url)
      // We don't want entire hostname, only the specific org
      const hostnameParts = urlObj.hostname.split(".")
      const mainDomain = hostnameParts.slice(-2).join(".")

      if (mainDomain === "hoppscotch") {
        return "Hoppscotch"
      }

      return mainDomain || urlObj.hostname.replace(/^www\./, "")
    } catch {
      return url
    }
  }

  public isCurrentlyVendored(): boolean {
    const state = this.state$.value
    return (
      state.status === "connected" &&
      state.instance.type === this.getVendoredInstance().type
    )
  }

  public isCurrentlyConnectedTo(serverUrl: string): boolean {
    const state = this.state$.value
    if (state.status !== "connected") return false

    const instance = state.instance
    if (instance.type !== "server") return false

    return instance.serverUrl === this.normalizeUrl(serverUrl)
  }

  public normalizeUrl(url: string): string {
    try {
      const withProtocol = url.startsWith("http") ? url : `http://${url}`
      const urlObj = new URL(withProtocol)

      const pathSegments = urlObj.pathname.split("/").filter(Boolean)

      if (!pathSegments.includes("desktop-app-server")) {
        // We try `desktop-app-server` subpath first
        const withSubpath = new URL(withProtocol)
        withSubpath.pathname = `/desktop-app-server${urlObj.pathname}`

        // If it fails, fall back to the original URL with default port
        try {
          const re = withSubpath.toString().replace(/\/$/, "")
          return re
        } catch {
          if (!urlObj.port) {
            urlObj.port = "3200"
          }
          const re = urlObj.toString().replace(/\/$/, "")
          return re
        }
      }

      const re = urlObj.toString().replace(/\/$/, "")
      return re
    } catch (error) {
      return url
    }
  }

  private async loadSavedState(): Promise<void> {
    try {
      const savedState =
        await this.store.get<ConnectionState>("connectionState")

      if (savedState && savedState.status === "connected") {
        if (savedState.instance.type === "server") {
          this.state$.next(savedState)
          this.emit(this.state$.value)
        }
      }
    } catch (error) {
      console.error("Failed to load saved state:", error)
      this.state$.next({ status: "idle" })
    }
  }

  private async saveCurrentState(): Promise<void> {
    try {
      await this.store.set("connectionState", this.state$.value)
      await this.store.save()
    } catch (error) {
      console.error("Failed to save current state:", error)
    }
  }

  private async loadRecentInstances(): Promise<void> {
    try {
      const instances =
        (await this.store.get<ServerInstance[]>("recentInstances")) || []

      const sortedInstances = instances.sort(
        (a, b) =>
          new Date(b.lastUsed).getTime() - new Date(a.lastUsed).getTime()
      )

      this.recentInstances$.next(sortedInstances)
    } catch (error) {
      console.error("Failed to load recent instances:", error)
      this.recentInstances$.next([])
    }
  }

  private async saveRecentInstances(): Promise<void> {
    try {
      await this.store.set("recentInstances", this.recentInstances$.value)
      await this.store.save()
    } catch (error) {
      console.error("Failed to save recent instances:", error)
    }
  }

  private async updateRecentInstance(instance: ServerInstance): Promise<void> {
    try {
      const currentInstances = [...this.recentInstances$.value]
      const instances = currentInstances.filter(
        (item) => item.serverUrl !== instance.serverUrl
      )

      instances.unshift(instance)

      if (instances.length > MAX_RECENT_INSTANCES) {
        instances.length = MAX_RECENT_INSTANCES
      }

      this.recentInstances$.next(instances)
      await this.saveRecentInstances()

      console.log(
        `Updated recent instances. Current count: ${instances.length}`
      )
    } catch (error) {
      console.error("Failed to update recent instance:", error)
    }
  }
}

import * as E from "fp-ts/Either"
import { Service } from "dioc"
import { MaybeRef, refWithControl } from "@vueuse/core"
import { AxiosRequestConfig, AxiosResponse } from "axios"
import type { getI18n } from "~/modules/i18n"
import { throwError } from "~/helpers/functional/error"
import { Component, Ref, computed, reactive, watch, unref, markRaw } from "vue"

/**
 * Defines the response data from an interceptor request run.
 */
export type NetworkResponse = AxiosResponse<unknown> & {
  config?: {
    timeData?: {
      startTime: number
      endTime: number
    }
  }
  /**
   * Optional additional fields with special optional metadata that can be used
   */
  additional?: {
    /**
     * By the HTTP spec, we can have multiple headers with the same name, but
     * this is not accessible in the AxiosResponse type as the headers there are Record<string, string>
     * (and hence cannot have secondary values).
     *
     * If this value is present, headers can be read from here which will have the data.
     */
    multiHeaders?: Array<{
      key: string
      value: string
    }>
  }
}

/**
 * Defines the errors that can occur during interceptor request run.
 */
export type InterceptorError =
  | "cancellation"
  | {
      humanMessage: {
        heading: (t: ReturnType<typeof getI18n>) => string
        description: (t: ReturnType<typeof getI18n>) => string
      }
      error?: unknown
      component?: Component
    }

/**
 * Defines the result of an interceptor request run.
 */
export type RequestRunResult<Err extends InterceptorError = InterceptorError> =
  {
    /**
     * Cancels the interceptor request run.
     */
    cancel: () => void

    /**
     * Promise that resolves when the interceptor request run is finished.
     */
    response: Promise<E.Either<Err, NetworkResponse>>
  }

/**
 * Defines whether an interceptor is selectable or not
 */
export type InterceptorSelectableStatus<CustomComponentProps = any> =
  | { type: "selectable" }
  | {
      type: "unselectable"
      reason:
        | {
            type: "text"
            text: (t: ReturnType<typeof getI18n>) => string
            action?: {
              text: (t: ReturnType<typeof getI18n>) => string
              onActionClick: () => void
            }
          }
        | {
            type: "custom"
            component: Component<CustomComponentProps>
            props: CustomComponentProps
          }
    }

/**
 * An interceptor is an object that defines how to run a Hoppscotch request.
 */
export type Interceptor<Err extends InterceptorError = InterceptorError> = {
  /**
   * The ID of the interceptor. This should be unique across all registered interceptors.
   */
  interceptorID: string

  /**
   * The function that returns the name of the interceptor.
   * @param t The i18n function.
   */
  name: (t: ReturnType<typeof getI18n>) => MaybeRef<string>

  /**
   * Defines whether the interceptor has support for cookies.
   * If this field is undefined, it is assumed as *not supporting* cookies.
   */
  supportsCookies?: boolean

  /**
   * Defines whether the interceptor has support for Digest Auth.
   * If this field is undefined, it is assumed as *not supporting* the Digest Auth type.
   */
  supportsDigestAuth?: boolean

  /**
   * Defines whether the interceptor has support for Binary (file) content type.
   * If this field is undefined, it is assumed as *supporting* the Binary content type.
   */
  supportsBinaryContentType?: boolean

  /**
   * Defines what to render in the Interceptor section of the Settings page.
   * Use this space to define interceptor specific settings.
   * Not setting this will lead to nothing being rendered about this interceptor in the settings page.
   */
  settingsPageEntry?: {
    /**
     * The title of the interceptor entry in the settings page.
     */
    entryTitle: (t: ReturnType<typeof getI18n>) => string

    /**
     * The component to render in the settings page.
     */
    component: Component
  }

  /**
   * Defines what to render under the entry for the interceptor in the Interceptor selector.
   */
  selectorSubtitle?: Component

  /**
   * Defines whether the interceptor is selectable or not.
   */
  selectable: MaybeRef<InterceptorSelectableStatus<unknown>>

  /**
   * Runs the interceptor on the given request.
   * NOTE: Make sure this function doesn't throw, instead when an error occurs, return a Left Either with the error.
   * @param request The request to run the interceptor on.
   */
  runRequest: (request: AxiosRequestConfig) => RequestRunResult<Err>
}

/**
 * This service deals with the registration and execution of
 * interceptors for request execution.
 */
export class InterceptorService extends Service {
  public static readonly ID = "INTERCEPTOR_SERVICE"

  private interceptors: Map<string, Interceptor> = reactive(new Map())

  /**
   * The ID of the currently selected interceptor.
   * If `null`, there are no interceptors registered or none can be selected.
   */
  public currentInterceptorID: Ref<string | null> = refWithControl(
    null as string | null,
    {
      onBeforeChange: (value) => {
        if (!value) {
          // Only allow `null` if there are no interceptors
          return this.availableInterceptors.value.length === 0
        }

        if (value && !this.interceptors.has(value)) {
          console.warn(
            "Attempt to set current interceptor ID to unknown ID is ignored"
          )
          return false
        }

        return true
      },
    }
  )

  /**
   * List of interceptors that are registered with the service.
   */
  public availableInterceptors = computed(() =>
    Array.from(this.interceptors.values())
  )

  /**
   * Gives an instance to the current interceptor.
   *  NOTE: Do not update from here, this is only for reading.
   */
  public currentInterceptor = computed(() => {
    if (this.currentInterceptorID.value === null) return null

    return this.interceptors.get(this.currentInterceptorID.value)
  })

  override onServiceInit() {
    // If the current interceptor is unselectable, select the first selectable one, else null
    watch([() => this.interceptors, this.currentInterceptorID], () => {
      if (!this.currentInterceptorID.value) return

      const interceptor = this.interceptors.get(this.currentInterceptorID.value)

      if (!interceptor) {
        this.currentInterceptorID.value = null
        return
      }

      if (unref(interceptor.selectable).type === "unselectable") {
        this.currentInterceptorID.value =
          this.availableInterceptors.value.filter(
            (interceptor) => unref(interceptor.selectable).type === "selectable"
          )[0]?.interceptorID ?? null
      }
    })
  }

  /**
   * Register an interceptor with the service.
   * @param interceptor The interceptor to register
   */
  public registerInterceptor(interceptor: Interceptor) {
    // markRaw so that interceptor state by itself is not fully marked reactive
    this.interceptors.set(interceptor.interceptorID, markRaw(interceptor))

    if (this.currentInterceptorID.value === null) {
      this.currentInterceptorID.value = interceptor.interceptorID
    }
  }

  /**
   * Runs a request through the currently selected interceptor.
   * @param req The request to run
   * @throws If no interceptor is selected
   */
  public runRequest(req: AxiosRequestConfig): RequestRunResult {
    if (!this.currentInterceptorID.value) {
      throw new Error("No interceptor selected")
    }

    const interceptor =
      this.interceptors.get(this.currentInterceptorID.value) ??
      throwError(
        "Current Interceptor ID is not found in the list of registered interceptors"
      )

    return interceptor.runRequest(req)
  }

  public static convertArrayBufferToString(data: ArrayBuffer): string {
    return new TextDecoder().decode(data).replace(/\0+$/, "")
  }
}

import * as E from "fp-ts/Either"
import { Service } from "dioc"
import { Component, computed, reactive, watchEffect, markRaw } from "vue"
import type { getI18n } from "~/modules/i18n"
import {
  RelayRequest,
  RelayResponse,
  RelayError,
  RelayCapabilities,
} from "@hoppscotch/kernel"

export function isCancellationError(
  error: KernelInterceptorError
): error is "cancellation" {
  return error === "cancellation"
}

export type SelectableStatus<Props = unknown> =
  | { type: "selectable" }
  | {
      type: "unselectable"
      reason:
        | {
            type: "text"
            text: (t: ReturnType<typeof getI18n>) => string
            action?: {
              text: (t: ReturnType<typeof getI18n>) => string
              onActionClick: () => void
            }
          }
        | {
            type: "custom"
            component: Component<Props>
            props: Props
          }
    }

export type KernelInterceptorError =
  | "cancellation"
  | {
      humanMessage: {
        heading: (t: ReturnType<typeof getI18n>) => string
        description: (t: ReturnType<typeof getI18n>) => string
      }
      error: RelayError
      component?: Component<RelayError>
    }

export type ExecutionResult<
  Err extends KernelInterceptorError = KernelInterceptorError,
> = {
  cancel: () => Promise<void>
  response: Promise<E.Either<Err, RelayResponse>>
}

export type KernelInterceptor<
  Err extends KernelInterceptorError = KernelInterceptorError,
> = {
  id: string
  name: (t: ReturnType<typeof getI18n>) => string
  settingsEntry?: {
    title: (t: ReturnType<typeof getI18n>) => string
    component: Component
  }
  subtitle?: Component
  selectable: SelectableStatus
  capabilities: RelayCapabilities
  execute: (request: RelayRequest) => ExecutionResult<Err>
}

export class KernelInterceptorService extends Service {
  public static readonly ID = "KERNEL_INTERCEPTOR_SERVICE"

  private readonly state = reactive({
    interceptors: new Map<string, KernelInterceptor>(),
    currentId: null as string | null,
  })

  public readonly current = computed(() =>
    this.state.currentId
      ? this.state.interceptors.get(this.state.currentId)
      : null
  )

  public readonly available = computed(() =>
    Array.from(this.state.interceptors.values())
  )

  public getCurrentId(): string | null {
    return this.state.currentId
  }

  override onServiceInit(): void {
    this.setupInterceptorValidation()
  }

  private setupInterceptorValidation(): void {
    watchEffect(() => {
      if (!this.state.currentId) return

      const currentInterceptor = this.state.interceptors.get(
        this.state.currentId
      )

      if (!this.validateCurrentInterceptor(currentInterceptor)) {
        this.resetToSelectableInterceptor()
      }
    })
  }

  private validateCurrentInterceptor(
    interceptor: KernelInterceptor | undefined
  ): boolean {
    if (!interceptor) {
      this.state.currentId = null
      return false
    }

    return interceptor.selectable.type === "selectable"
  }

  private resetToSelectableInterceptor(): void {
    const selectableInterceptor = this.available.value.find(
      (int) => int.selectable.type === "selectable"
    )
    this.state.currentId = selectableInterceptor?.id ?? null
  }

  public register(interceptor: KernelInterceptor): void {
    this.state.interceptors.set(interceptor.id, markRaw(interceptor))

    if (!this.state.currentId) {
      this.state.currentId = interceptor.id
    }
  }

  public setActive(id: string | null): void {
    if (!id) {
      this.handleNullIdActivation()
      return
    }

    if (!this.state.interceptors.has(id)) {
      console.warn("Attempted to set unknown interceptor as active", id)
      return
    }

    this.state.currentId = id
  }

  private handleNullIdActivation(): void {
    this.state.currentId =
      this.available.value.length === 0 ? null : this.state.currentId
  }

  public execute(req: RelayRequest): ExecutionResult {
    const interceptor = this.validateAndGetActiveInterceptor()
    return interceptor.execute(req)
  }

  private validateAndGetActiveInterceptor(): KernelInterceptor {
    if (!this.state.currentId) {
      throw new Error("No active interceptor")
    }

    const interceptor = this.state.interceptors.get(this.state.currentId)
    if (!interceptor) {
      throw new Error("Active interceptor not found")
    }

    return interceptor
  }
}

