    const result = await getOpenAiModels({
      apiKey: emailAccount.user.aiApiKey,
    });
    return NextResponse.json(result);
  } catch (error) {
    req.logger.error("Failed to get OpenAI models", { error });
    return NextResponse.json([]);
  }
});

