            onClick={() => {
              navigator.clipboard.writeText(newToken);
              toast.success(t("copied_to_clipboard"));
            }}
            className="btn btn-primary w-fit mx-auto"
          >
            {t("copy_to_clipboard")}
          </button>
        </div>
      ) : (
        <>
