import { randomUUID } from 'crypto';
import { createTRPCRouter, protectedProcedure } from '@/server/api/trpc';
import { db } from '@/server/db';
import { hashPassword } from '@/server/services/hash.service';
import { getOrganizationBySlug } from '@/server/services/organization.service';
import { z } from 'zod';

export const clientRouter = createTRPCRouter({
  list: protectedProcedure
    .input(
      z.object({
        organizationSlug: z.string(),
      })
    )
    .query(async ({ input }) => {
      const organization = await getOrganizationBySlug(input.organizationSlug);
      return db.client.findMany({
        where: {
          organization_id: organization.id,
        },
        include: {
          project: true,
        },
      });
    }),
  get: protectedProcedure
    .input(
      z.object({
        id: z.string(),
      })
    )
    .query(({ input }) => {
      return db.client.findUniqueOrThrow({
        where: {
          id: input.id,
        },
      });
    }),
  update: protectedProcedure
    .input(
      z.object({
        id: z.string(),
        name: z.string(),
        cors: z.string(),
      })
    )
    .mutation(({ input }) => {
      return db.client.update({
        where: {
          id: input.id,
        },
        data: {
          name: input.name,
          cors: input.cors,
        },
      });
    }),
  create: protectedProcedure
    .input(
      z.object({
        name: z.string(),
        projectId: z.string(),
        organizationSlug: z.string(),
        withCors: z.boolean().default(true),
      })
    )
    .mutation(async ({ input }) => {
      const organization = await getOrganizationBySlug(input.organizationSlug);
      const secret = randomUUID();
      const client = await db.client.create({
        data: {
          organization_id: organization.id,
          project_id: input.projectId,
          name: input.name,
          secret: input.withCors ? null : await hashPassword(secret),
        },
      });

      return {
        clientSecret: input.withCors ? null : secret,
        clientId: client.id,
        cors: client.cors,
      };
    }),
  remove: protectedProcedure
    .input(
      z.object({
        id: z.string(),
      })
    )
    .mutation(async ({ input }) => {
      await db.client.delete({
        where: {
          id: input.id,
        },
      });
      return true;
    }),
});

