export const VerifyEmailForm = () => {
  const { isLoading, setErrorMessage, setSuccessMessage, setIsLoading } = useContext(AuthContext)
  const location = useLocation()
  const token = new URLSearchParams(location.search).get('token')

  async function submitForm() {
    if (!token) {
      setErrorMessage({
        title:
          'The token is missing from the URL. Please check the link you received in your email.',
      })
      return
    }
    setIsLoading(true)
    setErrorMessage(null)
    setSuccessMessage(null)
    try {
      await verifyEmail({ token })
      setSuccessMessage('Your email has been verified. You can now log in.')
    } catch (error) {
      setErrorMessage({
        title: error.message,
        description: error.data?.data?.message,
      })
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
    submitForm()
  }, [location])

  return <>{isLoading && <Message>Verifying email...</Message>}</>
}

import { signup } from '../../../email/actions/signup'
import { login } from '../../../email/actions/login'

export function useEmail({
  onError,
  showEmailVerificationPending,
  isEmailVerificationRequired,
  onLoginSuccess,
  isLogin,
}: {
  onError: (error: Error) => void
  showEmailVerificationPending: () => void
  onLoginSuccess: () => void
  isLogin: boolean
  isEmailVerificationRequired: boolean
}) {
  async function handleSubmit(data) {
    try {
      if (isLogin) {
        await login(data)
        onLoginSuccess()
      } else {
        await signup(data)
        if (isEmailVerificationRequired) {
          showEmailVerificationPending()
        } else {
          await login(data)
          onLoginSuccess()
        }
      }
    } catch (err: unknown) {
      onError(err as Error)
    }
  }

  return {
    handleSubmit,
  }
}

