import type { FC, PropsWithChildren } from 'react';
import React, { useMemo, useState } from 'react';
import { Collaborator } from './Collaborator';
import { RoleSelect } from './RoleSelect';

interface ICollaborators {
  spaceId: string;
  role: IRole;
}

const filterCollaborators = (search: string, collaborators?: ListSpaceCollaboratorVo) => {
  if (!search) return collaborators;
  return collaborators?.filter(({ userName, email }) => {
    const searchLower = search.toLowerCase();
    const usernameLower = userName.toLowerCase();
    const emailLower = email.toLowerCase();
    return !search || usernameLower.includes(searchLower) || emailLower.includes(searchLower);
  });
};

export const Collaborators: FC<PropsWithChildren<ICollaborators>> = (props) => {
  const { spaceId, role, children } = props;
  const [search, setSearch] = useState<string>('');
  const [applySearch, setApplySearch] = useState<string>(search);
  const queryClient = useQueryClient();
  const { user } = useSession();
  const { t } = useTranslation('common');
  const dayjs = useLanDayjs();

  const { data: collaborators } = useQuery({
    queryKey: ReactQueryKeys.spaceCollaboratorList(spaceId),
    queryFn: ({ queryKey }) => getSpaceCollaboratorList(queryKey[1]).then((res) => res.data),
  });

  const { mutate: updateCollaborator, isLoading: updateCollaboratorLoading } = useMutation({
    mutationFn: updateSpaceCollaborator,
    onSuccess: async () => {
      await queryClient.invalidateQueries(ReactQueryKeys.spaceCollaboratorList(spaceId));
    },
  });

  const { mutate: deleteCollaborator, isLoading: deleteCollaboratorLoading } = useMutation({
    mutationFn: deleteSpaceCollaborator,
    onSuccess: async () => {
      await queryClient.invalidateQueries(ReactQueryKeys.spaceCollaboratorList(spaceId));
    },
  });

  const collaboratorsFiltered = useMemo(() => {
    return filterCollaborators(applySearch, collaborators);
  }, [applySearch, collaborators]);

  const hasGrantRolePermission = hasPermission(role, 'space|grant_role');

  const setApplySearchDebounced = useMemo(() => {
    return debounce(setApplySearch, 200);
  }, []);

  return (
    <div>
      <div className="mb-6 flex items-center gap-x-4">
        <Input
          className="h-8"
          type="search"
          placeholder={t('invite.dialog.collaboratorSearchPlaceholder')}
          value={search}
          onChange={(e) => {
            const value = e.target.value;
            setSearch(value);
            setApplySearchDebounced(value);
          }}
        />
        {children}
      </div>
      <div className="space-y-5">
        {collaboratorsFiltered?.map(({ userId, userName, email, role, avatar, createdTime }) => (
          <div key={userId} className="relative flex items-center gap-3 pr-6">
            <Collaborator name={userName} email={email} avatar={avatar} />
            <div className="text-xs text-muted-foreground">
              {t('invite.dialog.collaboratorJoin', {
                joinTime: dayjs(createdTime).fromNow(),
              })}
            </div>
            <RoleSelect
              value={role}
              disabled={updateCollaboratorLoading || userId === user.id || !hasGrantRolePermission}
              onChange={(role) =>
                updateCollaborator({ spaceId, updateSpaceCollaborateRo: { userId, role } })
              }
            />
            {userId !== user.id && hasGrantRolePermission && (
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      className="absolute right-0 h-auto p-0 hover:bg-inherit"
                      size="sm"
                      variant="ghost"
                      disabled={deleteCollaboratorLoading}
                      onClick={() => deleteCollaborator({ spaceId, userId })}
                    >
                      <X className="size-4 cursor-pointer text-muted-foreground opacity-70 hover:opacity-100" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>
                    <p>{t('invite.dialog.collaboratorRemove')}</p>
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

import { useMutation, useQueryClient } from '@tanstack/react-query';
import type { IRole } from '@teable/core';
import { Role, hasPermission } from '@teable/core';
import { X } from '@teable/icons';
import { createSpaceInvitationLink, emailSpaceInvitation } from '@teable/openapi';
import { ReactQueryKeys, useSpaceRoleStatic } from '@teable/sdk';
import { Button, cn } from '@teable/ui-lib';
import { map } from 'lodash';
import { Trans, useTranslation } from 'next-i18next';
import { useMemo, useState } from 'react';
import { z } from 'zod';
import { RoleSelect } from './RoleSelect';
import { getRolesWithLowerPermissions } from './utils';

interface IInvite {
  className?: string;
  spaceId: string;
  role: IRole;
}

export const Invite: React.FC<IInvite> = (props) => {
  const { className, spaceId, role } = props;
  const queryClient = useQueryClient();
  const { t } = useTranslation('common');

  const [inviteType, setInviteType] = useState<'link' | 'email'>('email');
  const [inviteRole, setInviteRole] = useState<IRole>(role);
  const [email, setEmail] = useState<string>('');
  const [inviteEmails, setInviteEmails] = useState<string[]>([]);

  const { mutate: emailInvitation, isLoading: updateCollaboratorLoading } = useMutation({
    mutationFn: emailSpaceInvitation,
    onSuccess: async () => {
      await queryClient.invalidateQueries(ReactQueryKeys.spaceCollaboratorList(spaceId));
    },
  });

  const sendInviteEmail = async () => {
    await emailInvitation({
      spaceId,
      emailSpaceInvitationRo: {
        emails: inviteEmails.length ? inviteEmails : [email],
        role: inviteRole,
      },
    });
    initEmail();
  };

  const { mutate: createInviteLinkRequest, isLoading: createInviteLinkLoading } = useMutation({
    mutationFn: createSpaceInvitationLink,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['invite-link-list'] });
    },
  });

  const createInviteLink = async () => {
    await createInviteLinkRequest({ spaceId, createSpaceInvitationLinkRo: { role: inviteRole } });
    setInviteRole(Role.Creator);
  };

  const changeInviteType = (inviteType: 'link' | 'email') => {
    initEmail();
    setInviteRole(Role.Creator);
    setInviteType(inviteType);
  };

  const initEmail = () => {
    setInviteEmails([]);
    setEmail('');
  };

  const emailInputChange = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.code === 'Backspace' && !email?.length) {
      setInviteEmails(inviteEmails.slice(0, inviteEmails.length - 1));
      return;
    }
    if (
      ['Space', 'Enter'].includes(e.code) &&
      email &&
      z.string().email().safeParse(email).success &&
      !inviteEmails.includes(email)
    ) {
      setEmail('');
      setInviteEmails(inviteEmails.concat(email));
      e.preventDefault();
    }
  };

  const deleteEmail = (email: string) => {
    setInviteEmails((inviteEmails) => inviteEmails.filter((inviteEmail) => email !== inviteEmail));
  };

  const spaceRoleStatic = useSpaceRoleStatic();
  const filterRoles = useMemo(
    () => map(getRolesWithLowerPermissions(role, spaceRoleStatic), 'role'),
    [role, spaceRoleStatic]
  );

  const isEmailInputValid = useMemo(() => z.string().email().safeParse(email).success, [email]);

  const EmailInvite = (
    <div>
      <div className="flex gap-2">
        <div className="flex max-h-64 min-h-8 flex-1 flex-wrap gap-1 overflow-y-auto rounded-md border border-input bg-background p-1 text-sm shadow-sm transition-colors">
          {inviteEmails.map((email) => (
            <div
              key={email}
              className="flex h-6 items-center rounded-full bg-muted px-2 text-xs text-muted-foreground"
            >
              {email}
              <X
                className="ml-1 cursor-pointer hover:opacity-70"
                onClick={() => deleteEmail(email)}
              />
            </div>
          ))}
          <input
            className="h-6 flex-auto bg-background text-xs outline-none"
            placeholder={t('invite.dialog.emailPlaceholder')}
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            onKeyDown={emailInputChange}
          />
        </div>
        <RoleSelect value={inviteRole} filterRoles={filterRoles} onChange={setInviteRole} />
      </div>
      <Button
        className="mt-2"
        size={'sm'}
        disabled={(!isEmailInputValid && inviteEmails.length === 0) || updateCollaboratorLoading}
        onClick={sendInviteEmail}
      >
        {t('invite.dialog.emailSend')}
      </Button>
    </div>
  );

  const LinkInvite = (
    <div>
      <div className="flex items-center text-sm">
        <Trans ns="common" i18nKey={'invite.dialog.linkPlaceholder'}>
          <RoleSelect
            className="mx-1"
            filterRoles={filterRoles}
            value={inviteRole}
            onChange={setInviteRole}
          />
        </Trans>
      </div>
      <Button
        className="mt-2"
        size={'sm'}
        disabled={createInviteLinkLoading}
        onClick={createInviteLink}
      >
        {t('invite.dialog.linkSend')}
      </Button>
    </div>
  );

  const showLink = hasPermission(role, 'space|invite_link');

  if (!showLink) {
    return <div className={cn(className, 'rounded bg-muted px-4 py-2')}>{EmailInvite}</div>;
  }

  return (
    <div className={cn(className, 'rounded bg-muted px-4 py-2')}>
      <div className="pb-2">
        <Button
          className="mr-6 p-0 data-[state=active]:underline"
          data-state={inviteType === 'email' ? 'active' : 'inactive'}
          variant={'link'}
          onClick={() => changeInviteType('email')}
        >
          {t('invite.dialog.tabEmail')}
        </Button>
        <Button
          className="p-0 data-[state=active]:underline"
          data-state={inviteType === 'link' ? 'active' : 'inactive'}
          variant={'link'}
          onClick={() => changeInviteType('link')}
        >
          {t('invite.dialog.tabLink')}
        </Button>
      </div>
      <div>{inviteType === 'email' ? EmailInvite : LinkInvite}</div>
    </div>
  );
};

