model Scan {
  id String @id @default(cuid())

  latitude  String?
  longitude String?

  userAgent String?

  // When a logged in user scanned the code, we store it here
  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)
  userId String?

  // Set only for a QR scan. A barcode or SAM ID scan has no QR.
  qr   Qr?     @relation(fields: [qrId], references: [id], onDelete: SetNull)
  qrId String?

  // The scanned QR id as a raw string, kept when the QR is deleted. NULL for a
  // barcode or SAM ID scan; `code` carries the scanned value for every type.
  rawQrId String?

  // What kind of code was scanned, and its value exactly as scanned (a QR id,
  // a barcode value or a SAM ID).
  codeType ScanCodeType @default(QR)
  code     String?

  // Set only for a barcode scan.
  barcode   Barcode? @relation(fields: [barcodeId], references: [id], onDelete: SetNull)
  barcodeId String?

  // What the code resolved to at scan time. Stamped on the row so the last
  // scan of an asset or kit is read by the entity, whichever code was scanned,
  // and survives the code being relinked or deleted.
  asset          Asset?        @relation(fields: [assetId], references: [id], onDelete: SetNull)
  assetId        String?
  kit            Kit?          @relation(fields: [kitId], references: [id], onDelete: SetNull)
  kitId          String?
  // The workspace the code resolved in. Every scan has one: a code no
  // workspace has claimed is not recorded.
  organization   Organization  @relation(fields: [organizationId], references: [id], onDelete: Cascade)
  organizationId String

  // Which surface recorded the scan. NULL on rows written before it was
  // tracked: their source cannot be told honestly.
  source ScanSource?

  // This will be true if the user manually created the scan by using "Update GPS coordinates"
  manuallyGenerated Boolean @default(false)

  // DateTime
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // Indexes for foreign keys
  @@index([qrId])
  @@index([userId])
  // Serves the scan lookups by QR id. Scan is a global, append-only table
  // (never pruned), so every read must seek an index rather than scan all
  // tenants' history; createdAt lets a top-1 DESC sort stop early.
  @@index([rawQrId, createdAt])
  // Serve the last-scan card on the asset overview and the kit page:
  // WHERE assetId|kitId = ? ORDER BY createdAt DESC LIMIT 1.
  @@index([assetId, createdAt])
  @@index([kitId, createdAt])
  @@index([barcodeId])
  @@index([organizationId])
}

/// The kind of code a `Scan` recorded.
enum ScanCodeType {
  QR
  BARCODE
  SAM_ID
}

/// The surface that recorded a `Scan`.
enum ScanSource {
  /// The public QR page, `/qr/:qrId` (phone camera or web scanner "view")
  QR_LINK
  /// The web scanner's "View asset" action for a barcode or SAM ID
  WEB_SCANNER
  /// A web scanner drawer list (bookings, kits, locations, custody)
  WEB_DRAWER
  /// An audit scan, web or companion
  AUDIT
  /// The companion app's scanner
  COMPANION
  /// "Update GPS coordinates" on the asset page
  GPS_UPDATE
}

model Location {
  id          String  @id @default(cuid())
  name        String
  description String?
  address     String?

  // Cached geocoding coordinates
  latitude  Float?
  longitude Float?

  imageUrl     String?
  thumbnailUrl String?

  image   Image?  @relation(fields: [imageId], references: [id])
  imageId String? @unique

  // Datetime
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // Relationships
  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  userId String

  organization   Organization @relation(fields: [organizationId], references: [id], onUpdate: Cascade, onDelete: Cascade)
  organizationId String

  // Asset placement is via the `AssetLocation` pivot; `kits` stays a
  // direct relation since `Kit.locationId` remains a FK (kits have a
  // single location, like INDIVIDUAL assets).
  assetLocations AssetLocation[]
  kits           Kit[]
  notes          LocationNote[] @relation("LocationNotes")

  // Quantity custody taken from this location, and the stock movements
  // recorded against it. Both point at the location itself, never at an
  // `AssetLocation` row, so moving a kit or re-creating a placement keeps them.
  custodies       Custody[]
  consumptionLogs ConsumptionLog[]

  // Self-relation for nested locations
  parentId String?
  parent   Location?  @relation("LocationHierarchy", fields: [parentId], references: [id], onDelete: SetNull)
  children Location[] @relation("LocationHierarchy")

  // @@unique([lower(name), organizationId]) //prisma doesnt support case insensitive unique index yet
  // Indexes for foreign keys
  @@index([organizationId])
  @@index([userId])
  @@index([organizationId, parentId])
  // Trigram index for substring search from the asset-list search bar
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin, name: "Location_name_trgm_idx")
  // Trigram indexes for the locations index search, which also matches
  // description and address with ILIKE '%term%'
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin, name: "Location_description_trgm_idx")
  @@index([address(ops: raw("gin_trgm_ops"))], type: Gin, name: "Location_address_trgm_idx")
}

// Master data for roles
model Role {
  id   String @id @default(cuid())
  name Roles  @unique @default(USER)

  createdAt DateTime @default(now())
