model TeamMember {
  id   String @id @default(cuid())
  name String

  organization    Organization @relation(fields: [organizationId], references: [id], onUpdate: Cascade, onDelete: Cascade)
  organizationId  String
  custodies       Custody[]
  receivedInvites Invite[]
  user            User?        @relation(fields: [userId], references: [id], onUpdate: Cascade, onDelete: SetNull)
  userId          String?
  kitCustodies    KitCustody[]

  createdAt      DateTime        @default(now())
  updatedAt      DateTime        @updatedAt
  deletedAt       DateTime?
  bookings        Booking[]
  assetReminders  AssetReminder[]
  consumptionLogs ConsumptionLog[]
  teamMemberNotes TeamMemberNote[]

  // Booking notification settings
  alwaysNotifyBookingSettings BookingSettings[] @relation("BookingSettingsAlwaysNotify")
  bookingNotifications        Booking[]         @relation("BookingNotificationRecipients")

  // Special GIN index for optimization of simple search queries
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  // Indexes for foreign keys
