  scimExternalIds UserScimExternalId[]
  roleChangeLogs  RoleChangeLog[]
  teamMemberNotes     TeamMemberNote[]
  activityEvents      ActivityEvent[]


  // Migration flag to track if sequential IDs have been generated for this organization's existing assets
  hasSequentialIdsMigrated Boolean @default(false)

  // QR code display preference - which ID to show on QR code labels
  qrIdDisplayPreference QrIdDisplayPreference @default(QR_ID)

  // Branding preference for downloadable labels
  showShelfBranding Boolean @default(true)

  // Whether the booking checklist and audit receipt PDFs print the QR image.
  // Off means the sheet cannot be scanned in place of the label on the item.
  showQrCodesOnPdfs Boolean @default(true)

  // When the workspace was given the PDF documents of a paid plan (the
  // Check-out receipt). Null until its tier first includes PDF documents; set
  // once, so a document an admin deleted is never seeded back.
  paidPdfDocumentsSeededAt DateTime?

  // Custom footer text appended to workspace emails
