model CustomField {
  id       String  @id @default(cuid())
  name     String
  helpText String?
  required Boolean @default(false)
  active   Boolean @default(true)

  type    CustomFieldType   @default(TEXT)
  options String[]
  /// How a TEXT field's values are read. LINK requires a web link in every
  /// value; any other type stays PLAIN (enforced by a CHECK constraint).
  format  CustomFieldFormat @default(PLAIN)

  // Relationships
  organization   Organization @relation(fields: [organizationId], references: [id], onUpdate: Cascade, onDelete: Cascade)
  organizationId String

  createdBy User   @relation(fields: [userId], references: [id], onUpdate: Cascade)
  userId    String

  categories Category[]

  // Datetime
  createdAt               DateTime                @default(now())
  updatedAt               DateTime                @updatedAt
  deletedAt               DateTime?
  assetCustomFieldsValues AssetCustomFieldValue[]

  //@@unique([lower(name), organizationId]) //prisma doesnt support case insensitive unique index yet
  // Indexes for foreign keys
  @@index([organizationId])
  @@index([userId])
  @@index([organizationId, deletedAt])
}

enum CustomFieldType {
  TEXT
  OPTION
  BOOLEAN
  DATE
  MULTILINE_TEXT
  AMOUNT
  NUMBER
}

/// The format of a TEXT custom field. Unlike the type, it can change after the
/// field exists.
enum CustomFieldFormat {
  PLAIN
  LINK
}

model AssetCustomFieldValue {
  id String @id @default(cuid())

  // value String
  value Json //{raw: "actual data",valueText:"text type",valueBoolean:"boolean type" and so on... }

  // Relationships
  asset   Asset  @relation(fields: [assetId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  assetId String

  customField   CustomField @relation(fields: [customFieldId], references: [id], onUpdate: Cascade, onDelete: Cascade)
  customFieldId String

  // Datetime
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([assetId, customFieldId], name: "AssetCustomFieldValue_lookup_idx")
  // Index for foreign key
  @@index([customFieldId])
}

/// A custom field value an AssetModel gives the assets that join it.
///
/// `value` has the exact shape of `AssetCustomFieldValue.value`, so filling an
/// asset is a plain copy. Rows cascade away with their model or field.
model AssetModelCustomFieldDefault {
  id String @id @default(cuid())

  value Json

  assetModel   AssetModel @relation(fields: [assetModelId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  assetModelId String

  // Deliberately a plain column without a Prisma `@relation`: the migration
  // creates the FK to `CustomField("id")` with `ON DELETE CASCADE`, but a
  // back-relation on `CustomField` pushes the extended client's generics past
  // TS's recursion limit (TS2321) in `organization/service.server`. Services
  // read the field rows with a second query keyed on these ids. Because the
  // schema does not describe the FK, `prisma migrate dev` treats it as drift
  // and generates a drop for it. `pnpm db:prepare-migration` then runs
  // `src/post-migration.ts`, which strips that drop because the FK is listed in
  // `PROTECTED_FOREIGN_KEYS` (`src/protected-indexes.ts`). Plain
  // `prisma migrate dev` keeps the drop.
  customFieldId String

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([assetModelId, customFieldId])
  @@index([customFieldId])
}

