/**
 * Audit trail for all quantity changes on quantity-tracked assets.
 * Every event records who performed it, who received/returned items,
 * which booking it relates to, and the category of change.
 * Quantity is always positive — direction is determined by category.
 */
model ConsumptionLog {
  id        String              @id @default(cuid())
  asset     Asset               @relation(fields: [assetId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  assetId   String
  category  ConsumptionCategory
  quantity  Int // Always positive (Decision #9). The direction is the sign of `stockChange`.
  note      String?

  performedBy User   @relation(fields: [userId], references: [id])
  userId      String

  booking   Booking? @relation(fields: [bookingId], references: [id])
  bookingId String?

  custodian   TeamMember? @relation(fields: [custodianId], references: [id])
  custodianId String? // Who received/returned the items (if applicable)

  // Per-row attribution for QUANTITY_TRACKED check-in. With Polish-6 a
  // single (booking, asset) pair can have multiple BookingAsset rows
  // (kit-driven + standalone slices); aggregating dispositions by
  // (bookingId, assetId) alone can't distinguish "the kit slice is
  // done" from "all slices are done". `bookingAssetId` points the log
  // at the specific row the units were returned/consumed against.
  //
  // Declared as a plain column without a Prisma `@relation` accessor
  // (same pattern as `BookingAsset.assetKitId`) to avoid deep-generic
  // explosion on read paths that pull ConsumptionLog through Booking
  // / Asset graphs. The migration SQL creates a proper FK with
  // `ON DELETE SET NULL` so removing a BookingAsset row doesn't lose
  // history — the log stays but loses its per-row attribution.
  //
  // Legacy rows (pre-Polish-6, pre-this-migration) keep `NULL` and are
  // handled by a greedy-fill fallback in readers (kit-driven slices
  // attribute first, then standalone) so existing bookings still
  // render sensibly.
  bookingAssetId String?

  // The location the units left or arrived at, when the movement had one:
  // the custody source for CHECKOUT / RETURN / CONSUME, and the chosen
  // location for a RESTOCK / LOSS / ADJUSTMENT made at a location. NULL for
  // the unplaced units and for rows written before the column existed.
  location   Location? @relation(fields: [locationId], references: [id], onDelete: SetNull, onUpdate: Cascade)
  locationId String?

  // The signed change this row made to the stock held at `locationId`:
  // positive when units arrived, negative when they left, 0 for a CHECKOUT or
  // RETURN, which hands units out or takes them back without changing stock.
  // Where it is non-zero, a NULL `locationId` means the unplaced units, never
  // "unknown". From the asset's `stockLedgerStartedAt` on, the rows sum to the
  // live stock: per location to the manual `AssetLocation.quantity`, with a
  // NULL location to the unplaced units, and in total to `Asset.quantity`.
  // Written only through `recordStockChanges`
  // (`modules/consumption-log/stock-ledger.server.ts`). NULL on rows written
  // before the ledger recorded every change.
  stockChange Int?

  // Datetime
  createdAt DateTime @default(now())

  @@index([assetId, createdAt])
  @@index([userId])
  @@index([bookingId])
  @@index([custodianId])
  @@index([bookingAssetId])
  @@index([locationId])
}

/**
 * Explicit pivot table between Booking and Asset.
 * Replaces the implicit M2M (_AssetToBooking) via a rename migration in Phase 3.
 */
model BookingAsset {
  id        String  @id @default(cuid())
  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  bookingId String
  asset     Asset   @relation(fields: [assetId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  assetId   String
  quantity  Int     @default(1) // For quantity-tracked assets: how many booked

  // The model reservation this row discharged, when it came from one. `null`
  // for assets added directly — picked or scanned onto a booking with no
  // matching reservation to answer. That is most rows.
  //
  // A kit-driven row carries it too: a unit sitting inside a kit answers a
  // promise for units of its model exactly like a loose one, and the pool math
  // counts it either way. At most ONE row per (booking, asset) is ever stamped
  // — one physical unit discharges one reserved unit, however many rows the
  // asset holds on the booking.
  //
  // Without it the link is narrative only: `materializeModelRequestForAsset`
  // writes a note ("assigned X (Model A) — 2 remaining") and then the
  // relationship is gone. An assigned asset becomes indistinguishable from one
  // added by hand, so "which assets discharged the LED reservation?" is not
  // answerable from data, only by reading the activity feed.
  //
  // Deliberately a plain column without a Prisma `@relation` accessor, for
  // exactly the reason spelled out on `assetKitId` below — adding one more
  // relation to this model pushed the dynamic extended client's deep generic
  // past TS's recursion limit (TS2321), first in `organization/service.server`
  // and then in `asset/service.server`. Services read it directly:
  //   db.bookingAsset.findMany({ where: { bookingModelRequestId } })
  //   db.bookingAsset.create({ data: { ..., bookingModelRequestId } })
  //
  // `SET NULL` cascade (DB-enforced, not Prisma) means a vanished reservation
  // costs the row its provenance, never its place in the booking — the asset
  // stays physically committed. In practice this rarely fires:
  // `removeBookingModelRequest` refuses to delete a request with
  // `fulfilledQuantity > 0`, so the realistic path is the booking cascade,
  // which removes both rows together.
  bookingModelRequestId String?

  // Discriminator for "this booked slice came from a kit" vs "this booked
  // slice is standalone from the asset's free pool". Mirror of
  // `Custody.kitCustodyId` and `AssetLocation.assetKitId`. `null` =
  // standalone; non-null = kit-driven slice (FK points at `AssetKit.id`).
  //
  // Deliberately declared as a plain column without a Prisma `@relation`
  // accessor — the migration SQL creates a proper FK to `AssetKit("id")`
  // with `ON DELETE SET NULL ON UPDATE CASCADE`, but exposing the relation
  // at the Prisma type level pushes the dynamic extended client's deep
  // generic past TS's recursion limit (TS2321) in several services because
  // `Booking` (this row's grandparent) is a hub model with many relations.
  // Services query kit-driven rows directly via
  //   db.bookingAsset.findMany({ where: { assetKitId } })
  // and create them with
  //   db.bookingAsset.create({ data: { ..., assetKitId } })
  // — no Prisma-level relation traversal is needed.
  //
  // `SET NULL` cascade (DB-enforced, not Prisma) means removing an asset
  // from a kit converts the kit-driven booking slice into a standalone
  // reservation rather than silently shrinking an active booking. The
  // service layer emits a system note + audit event so the user sees the
  // conversion.
  assetKitId String?

  // Durable provenance: the `Kit` this slice was booked under. Unlike
  // `assetKitId` — which points at the `AssetKit` MEMBERSHIP row and is
  // `SET NULL`'d the moment the asset leaves the kit — this survives
  // membership changes, so a booking still knows the slice arrived as part
  // of a kit after the kit's contents change.
  //
  // Read by duplication, kit-drift, and display grouping (a slice whose asset
  // has left the kit still renders under that kit on bookings past the planning
  // stage). All availability/quantity math keeps using `assetKitId`, which
  // remains the source of truth for LIVE membership. The two are related,
  // never redundant:
  //   assetKitId NOT NULL -> sourceKitId NOT NULL, and they agree
  //   assetKitId NULL + sourceKitId NOT NULL -> detached kit residue
  //   both NULL                              -> genuine standalone slice
  //
  // Same plain-column treatment as `assetKitId` above: the FK to `Kit("id")`
  // with `ON DELETE SET NULL ON UPDATE CASCADE` is created in the migration
  // SQL, NOT via a Prisma `@relation`. Declaring the relation would add a
  // `bookingAssets` back-relation to `Kit` — a hub model — and push the
  // extended client's generics past TS's recursion limit (TS2321).
  //
  // `SET NULL` on kit deletion is deliberate: deleting a kit degrades its
  // slices to loose assets on existing bookings, which is exactly what
  // happened before this column existed, so no behaviour regresses.
  sourceKitId String?

  // Whether THIS slice is currently checked out on THIS booking, and by whom.
  // `checkedOutAt` NULL = never checked out here.
  //
  // This is the authoritative answer to "may this slice be checked in?", and
  // nothing else can give it:
  //   - `Asset.status` is global. An asset may be CHECKED_OUT by a DIFFERENT
  //     active booking while never having been checked out on this one.
  //   - `PartialBookingCheckout` records progressive scan SESSIONS only. The
  //     all-at-once checkout writes none at all, so the absence of rows says
  //     nothing about whether an asset went out — see the note on that model.
  //
  // Slice-grained rather than asset-grained because a QUANTITY_TRACKED asset is
  // split across several bookings and several slices at once, so no single
  // column on `Asset` could represent it.
  //
  // `checkedInAt` means FULLY reconciled, matching `PartialBookingCheckin`'s
  // `assetIds` semantics: a partially-returned qty-tracked slice stays NULL and
  // its flow back is tracked by `ConsumptionLog`.
  //
  // Same plain-column treatment as `assetKitId` / `sourceKitId` above — the
  // user columns are deliberately NOT Prisma `@relation`s. Adding another
  // relation to this model (whose grandparent `Booking` is a hub) pushes the
  // extended client's generics past TS's recursion limit (TS2321). Services
  // read the ids directly; no relation traversal is needed.
  checkedOutAt   DateTime? @db.Timestamptz(3)
  checkedOutById String?
  checkedInAt    DateTime? @db.Timestamptz(3)
  checkedInById  String?

  // How many of this slice's units have been sent out on this booking.
  //
  // `checkedOutAt` answers WHETHER any units left; this answers HOW MANY. A
  // QUANTITY_TRACKED slice can go out a few units at a time, and a timestamp
  // cannot express "3 of 10 are out" — so any reader deriving an obligation
  // from the timestamp alone must guess, and both guesses are wrong: the full
  // quantity demands back units that never moved, zero strands the ones that
  // did.
  //
  // CUMULATIVE units dispatched, never decremented. Units coming back are
  // counted by `ConsumptionLog`, so what is still out is
  // `checkedOutQuantity - dispositioned`. That split matches the counters the
  // booking surfaces already read (`bookedQuantity` / `checkedOutQuantity` /
  // `dispositionedQuantity`); this column is where the second one lives so it
  // no longer has to be reconstructed from scan sessions. A slice returned in
  // full and sent out again simply adds to it.
  //
  // Every writer that sends units out maintains it — the all-at-once checkout,
  // progressive checkout, and the kit-member propagation in `updateKitAssets`.
  // A writer that sets `checkedOutAt` without adding here leaves a slice whose
  // departure nothing can size.
  checkedOutQuantity Int @default(0)

  // The location a QUANTITY_TRACKED slice's units left from, recorded once,
  // when the slice is first checked out (`checkedOutQuantity` goes from 0).
  // A slice sent out again keeps it.
  //
  // Check-in reads it: units reported consumed, lost or damaged come off this
  // location's manual placement, so a pool placed at several locations loses
  // them where they actually came from. NULL = the pool's unplaced units, a
  // pool with no placements, or a slice checked out before this column
  // existed; check-in then lets the unplaced units absorb the drop, as before.
  //
  // A kit-driven slice records its kit's location (`Kit.locationId`, may be
  // NULL). That is for display only: kit units never come off a manual
  // placement.
  //
  // Same plain-column treatment as `assetKitId` / `sourceKitId` above: the FK
  // to `Location("id")` with `ON DELETE SET NULL ON UPDATE CASCADE` lives in
  // the migration SQL, not in a Prisma `@relation`, because one more relation
  // on this model (its grandparent `Booking` is a hub) pushes the extended
  // client's generics past TS's recursion limit (TS2321), and a
  // `bookingAssets` back-relation on `Location` would add another. Services
  // read the id and look the location up themselves.
  sourceLocationId String?

  // The old `@@unique([bookingId, assetId])` is replaced by two partial
  // unique indexes in the migration SQL (Postgres-only feature Prisma
  // can't express in the schema):
  //   BookingAsset_manual_unique: (bookingId, assetId) WHERE assetKitId IS NULL
  //   BookingAsset_kit_unique:    (bookingId, assetKitId) WHERE assetKitId IS NOT NULL
  // These let one standalone row coexist with N kit-driven rows for the
  // same (booking, asset) — required for the multi-kit qty-tracked case.

  @@index([assetId])
  @@index([assetKitId])
  @@index([sourceKitId])
  @@index([sourceLocationId])
}

model Booking {
  id String @id @default(cuid())

  name        String
  status      BookingStatus @default(DRAFT)
  description String?       @default("")

  activeSchedulerReference String?

  // Relationships
  creator   User   @relation("creator", fields: [creatorId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  creatorId String

  custodianUser   User?   @relation("custodian", fields: [custodianUserId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  custodianUserId String?

  custodianTeamMember   TeamMember? @relation(fields: [custodianTeamMemberId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  custodianTeamMemberId String?

  organization   Organization @relation(fields: [organizationId], references: [id], onUpdate: Cascade, onDelete: Cascade)
  organizationId String

  bookingAssets   BookingAsset[]
  consumptionLogs ConsumptionLog[]
  notes           BookingNote[]
  // Unfulfilled model-level requests (intent rows). Converted into
  // concrete `bookingAssets` at scan-to-assign time.
  modelRequests   BookingModelRequest[]

  tags             Tag[]
  partialCheckins  PartialBookingCheckin[]
  partialCheckouts PartialBookingCheckout[]

  // Datetime
  createdAt DateTime @default(now()) @db.Timestamptz(3)
  updatedAt DateTime @updatedAt @db.Timestamptz(3)
  from      DateTime @db.Timestamptz(3)
  to        DateTime @db.Timestamptz(3)

  // The period the booking was PLANNED for, as opposed to `from`/`to` above,
  // which hold the live period. Written while the booking is still being
  // planned (create, DRAFT edit, reserve) and frozen once it starts — every
  // later flow moves `from`/`to` and leaves these alone: extension pushes `to`
  // out, and early check-out / late or early-with-consent check-in rewrite the
  // dates to the actual moment. Booking Compliance measures returns against
  // these, so overwriting one after the booking starts erases the deadline the
  // custodian agreed to. Null only on rows created before the columns existed.
  originalFrom DateTime? @db.Timestamptz(3)
  originalTo   DateTime? @db.Timestamptz(3)

  // When a booking is auto-archived, we store the timestamp here
  autoArchivedAt DateTime? @db.Timestamptz(3)

  // True when the booking was archived directly from RESERVED — i.e. its end
  // date passed without ever being checked out/in. Such bookings were never
  // "returned", so return-behaviour reports (e.g. Booking Compliance) must
  // exclude them. Bookings archived from COMPLETE keep the default `false`.
  archivedWithoutCheckin Boolean @default(false)

  cancellationReason String?

  // Per-booking notification recipients (team members who receive all email updates for this booking)
  notificationRecipients TeamMember[] @relation("BookingNotificationRecipients")

  // Indexes for foreign keys
  @@index([creatorId])
  @@index([custodianTeamMemberId])
  @@index([custodianUserId])
  @@index([organizationId])
  // Speeds up status filtering when joining from Asset → Booking
  // (e.g. fetching ONGOING/OVERDUE bookings for asset custodian display)
  @@index([status])
  // Serves the bookings index default view (getBookings): WHERE
  // organizationId = ? ORDER BY "from" ASC LIMIT n. Column order (org first,
  // then the sort key, then id as the pagination tiebreaker) lets Postgres
  // seek the org and read the page straight off the index instead of
  // scanning + sorting every booking in the workspace. Same pattern as
  // Asset_organizationId_createdAt_id_idx.
  @@index([organizationId, from, id])
}

model BookingSettings {
  id String @id @default(cuid())

  bufferStartTime Int     @default(0) // Buffer time in hours for bookings. This is used to prevent short term bookings
  tagsRequired    Boolean @default(false) // Whether tags are required for bookings

  maxBookingLength               Int? // Maximum booking length in hours. NULL means no limit
  maxBookingLengthSkipClosedDays Boolean @default(false) // If true, the max booking length will skip closed days

  autoArchiveBookings Boolean @default(false) // Whether to automatically archive completed bookings
  autoArchiveDays     Int     @default(2) // Number of days after a booking is done before auto-archiving (shared by both auto-archive toggles)

  // Whether to automatically archive reserved bookings whose end date has passed
  // without ever being checked out (for teams that use bookings as a reservation
  // calendar and don't check out/in). Reuses autoArchiveDays for the delay.
  autoArchiveExpiredReservations Boolean @default(false)

  requireExplicitCheckinForAdmin      Boolean @default(false) // When true, admins must use explicit check-in (scanner) instead of quick check-in
  requireExplicitCheckinForSelfService Boolean @default(false) // When true, self-service users must use explicit check-in (scanner) instead of quick check-in

  requireExplicitCheckoutForAdmin       Boolean @default(false) // When true, admins must use explicit check-out (scan or select) instead of quick check-out
  requireExplicitCheckoutForSelfService Boolean @default(false) // When true, self-service users must use explicit check-out (scan or select) instead of quick check-out

  // Progressive check-in/out settings
  countKitsAsSingleUnit Boolean @default(false) // When true, the booking check-in progress bar treats each kit as one unit instead of counting the assets inside it

  // Notification settings
  notifyBookingCreator     Boolean @default(true) // Whether the booking creator receives email notifications
  notifyAdminsOnNewBooking Boolean @default(true) // Whether all admins receive a notification when a booking is reserved
  alwaysNotifyTeamMembers  TeamMember[] @relation("BookingSettingsAlwaysNotify") // Team members who always receive ALL booking email notifications

  // Relationships
  organization   Organization @relation(fields: [organizationId], references: [id], onUpdate: Cascade, onDelete: Cascade)
  organizationId String       @unique

  // Datetime
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // Index for foreign key
  @@index([organizationId])
}

/// A progressive check-in SESSION, mirroring PartialBookingCheckout.
///
/// `assetIds` lists only FULLY reconciled assets: INDIVIDUAL always, and
/// QUANTITY_TRACKED only once its remaining units hit zero (partial returns
/// live in `ConsumptionLog`). Completing a booking outright writes no row here,
/// so the same warning applies — absence is not evidence of anything.
/// `BookingAsset.checkedInAt` is the per-slice fact.
model PartialBookingCheckin {
  id String @id @default(cuid())

  // Track which assets were checked in during this session
  assetIds     String[] // Array of asset IDs checked in
  checkinCount Int // Number of assets checked in (for quick reference)

  // Metadata
  checkinTimestamp DateTime @default(now()) @db.Timestamptz(3)

  // Relationships
  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)
  bookingId String

  checkedInBy   User   @relation("PartialCheckinUser", fields: [checkedInById], references: [id])
  checkedInById String

  // Timestamps
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([bookingId])
  @@index([checkedInById])
  @@index([checkinTimestamp])
  @@index([bookingId, checkinTimestamp]) // Composite for efficient booking history queries
}

/// A progressive checkout SESSION: one scan batch, covering N assets via the
/// positional `assetIds` / `quantities` / `bookingAssetIds` arrays.
///
/// Records sessions and the units they claimed — NOT whether an asset is out.
/// The all-at-once checkout (`checkoutBooking`, the Check out button) flips
/// statuses and writes NO row here, so **absence proves nothing** and must never
/// be read as "was not checked out". Reading it that way is what let a single
/// later scan mark every button-checked-out asset on a booking as
/// "never checked out". `BookingAsset.checkedOutAt` answers that question.
model PartialBookingCheckout {
  id String @id @default(cuid())

  // Track which assets were checked out during this session
  assetIds      String[] // Array of asset IDs checked out
  // Units checked out per entry in `assetIds` (positional alignment).
  // INDIVIDUAL assets always record `1`. QUANTITY_TRACKED slices record the
  // unit count submitted for the matching `bookingAssetId`. Empty default
  // keeps legacy rows (written before Wave B) readable without a backfill.
  quantities    Int[]    @default([])
  // BookingAsset (slice) IDs per entry in `assetIds` (positional alignment
  // with `assetIds`/`quantities`). Disambiguates a QUANTITY_TRACKED asset that
  // is booked as multiple slices (e.g. standalone + kit member). An empty
  // string `""` element means "no specific slice known → greedy attribution";
  // Prisma `String[]` cannot hold `null`, so `""` is the sentinel. Empty
  // default keeps legacy rows readable without a backfill.
  bookingAssetIds String[] @default([])
  checkoutCount   Int // Number of assets checked out (for quick reference)

  // Metadata
  checkoutTimestamp DateTime @default(now()) @db.Timestamptz(3)

  // Relationships
  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)
  bookingId String

  checkedOutBy   User   @relation("PartialCheckoutUser", fields: [checkedOutById], references: [id])
  checkedOutById String

  // Timestamps
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([bookingId])
  @@index([checkedOutById])
  @@index([checkoutTimestamp])
  @@index([bookingId, checkoutTimestamp]) // Composite for efficient booking history queries
}

/// Native-app SSO web-delegated login — single-use session-handoff codes.
/// @see apps/webapp/app/routes/_auth+/oauth.callback.mobile.tsx
model MobileAuthCode {
  id String @id @default(cuid())

  // The user this code authorizes a session for.
  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  userId String

  // SHA-256 hash of the single-use plaintext code. The plaintext only ever
  // lives in the deeplink + the exchange request body — never stored.
  codeHash String @unique

  // PKCE (S256) challenge — base64url(SHA-256(verifier)). Mandatory in practice:
  // minting refuses a mobile SSO start without one, and redemption refuses a
  // code that carries none, so an unbound row can never be spent. Nullable only
  // because rows predating that rule may still exist; treat NULL as poison.
  codeChallenge String?

  // The web SSO session the code hands to the app, AES-256-GCM encrypted under
  // a key derived from the plaintext code, which is never stored: the row alone
  // cannot be decrypted. Cleared when the code is redeemed. NULL on rows minted
  // before sessions were stored, which redemption refuses.
  sessionCiphertext String?

  // Single-use guard: set when redeemed. A non-null value rejects reuse.
  consumedAt DateTime?

  // Short TTL — see MOBILE_AUTH_CODE_TTL_MS. Rejected once `now > expiresAt`.
  expiresAt DateTime

  createdAt DateTime @default(now())

  // Indexes for foreign keys
  @@index([userId])
  // For periodic cleanup of expired, unredeemed rows
  @@index([expiresAt])
}

/// The operating system a companion-app push token was issued for.
enum DevicePlatform {
  IOS
  ANDROID
}

/// One Expo push token per installed companion app. A token identifies a
/// device, not a person: when someone else signs in on the same phone, the
/// row moves to them. Pushes go only to rows where `disabledAt` is null.
/// @see apps/webapp/app/modules/push/service.server.ts
model PushToken {
  id String @id @default(cuid())

  // The `ExponentPushToken[...]` string the Expo push service addresses.
  token String @unique

  platform   DevicePlatform
  deviceName String?
  appVersion String?

  // Refreshed on every registration, so stale devices are visible.
  lastSeenAt DateTime

  // Set when Expo reports the device as no longer registered.
  disabledAt DateTime?

  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  userId String

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([userId])
}

/// A person's push notification switches. A missing row means every switch
/// is on, so no backfill is needed. The three category columns are named
/// after `PushCategory` in apps/webapp/app/modules/push/types.ts.
model NotificationPreference {
  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  userId String @id

  pushEnabled       Boolean @default(true)
  bookings          Boolean @default(true)
  audits            Boolean @default(true)
  stockAndReminders Boolean @default(true)

  updatedAt DateTime @updatedAt
}

model Kit {
  id String @id @default(cuid())

  name        String
  description String?
  status      KitStatus @default(AVAILABLE)

  image           String?
  imageExpiration DateTime?

  // `assets Asset[]` reverse relation on Asset.kitId.
  assetKits AssetKit[]
  custody  KitCustody?
  qrCodes  Qr[]
  barcodes Barcode[]
  reports  ReportFound[]
  scans    Scan[]

  // NOTE: there is intentionally no `bookingAssets BookingAsset[]`
  // back-relation here. `BookingAsset.sourceKitId` is a plain FK column
  // (DB-enforced, see the comment on that field) — exposing it as a Prisma
  // relation tips TS past its recursion limit (TS2321) because Booking is a
  // hub model with many relations. Services query it directly via
  // `db.bookingAsset.findMany({ where: { sourceKitId } })`. The `SET NULL`
  // cascade still fires at the DB level when a Kit row is deleted.

  organization   Organization @relation(fields: [organizationId], references: [id], onUpdate: Cascade, onDelete: Cascade)
  organizationId String

  createdBy   User   @relation(fields: [createdById], references: [id])
  createdById String

  category   Category? @relation(fields: [categoryId], references: [id])
  categoryId String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  location   Location? @relation(fields: [locationId], references: [id])
  locationId String?

  // Indexes for foreign keys
  @@index([createdById])
  @@index([organizationId])
  @@index([categoryId, organizationId]) //for basic category/organization lookups
  @@index([categoryId, organizationId, createdAt]) //for time-based queries
  @@index([categoryId, organizationId, name]) //for name-based searches
  @@index([categoryId, organizationId, status]) //for status filtering
}

enum KitStatus {
  AVAILABLE
  IN_CUSTODY
  CHECKED_OUT
}

model KitCustody {
  id String @id @default(cuid())

  custodian   TeamMember @relation(fields: [custodianId], references: [id])
  custodianId String

  kit   Kit    @relation(fields: [kitId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  kitId String @unique

  // Asset-side Custody rows inherited from this kit. Cascade-deleted
  // when the KitCustody row is removed (e.g. kit-level custody
  // released, or kit deleted), so operator-assigned custody on the
  // same asset stays untouched.
  inheritedCustody Custody[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // Index for foreign key
  @@index([custodianId])
}

/// Pivot linking an `Asset` to the `Kit` it belongs to.
///
/// `@@unique([assetId])` enforces "at most one kit per asset" today.
/// The structure already allows multi-row-per-asset; if multi-kit
/// allocation lands later, drop the `assetId` unique constraint and
/// add a type-aware single-row trigger + sum-within-total CONSTRAINT
/// TRIGGER (parallel to the Custody / BookingAsset pivots).
model AssetKit {
  id             String          @id @default(cuid())
  asset          Asset           @relation(fields: [assetId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  assetId        String
  kit            Kit             @relation(fields: [kitId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  kitId          String
  organization   Organization    @relation(fields: [organizationId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  organizationId String

  quantity       Int             @default(1)

  // Back-relation to the AssetLocation rows that are "driven by" this
  // kit membership — at most one per AssetKit. Created when the kit has
  // a location and the asset joins; auto-deleted via ON DELETE CASCADE
  // when the asset leaves the kit. See `AssetLocation.assetKit` and the
  // kit-cascade comments in `kit/service.server.ts`.
  assetLocations AssetLocation[]

  // NOTE: there is intentionally no `bookingAssets BookingAsset[]`
  // back-relation here. `BookingAsset.assetKitId` is a plain FK column
  // (DB-enforced, see the comment on that field) — exposing it as a
  // Prisma relation tips TS past its recursion limit (TS2321) because
  // Booking is a hub model with many relations. Services that need to
  // find kit-driven booking rows use `db.bookingAsset.findMany({
  // where: { assetKitId } })`. The `SET NULL` cascade still fires at
  // the DB level when an AssetKit row is deleted.

  createdAt      DateTime        @default(now())
  updatedAt      DateTime        @updatedAt

  // The "INDIVIDUAL asset belongs to at most one kit" cap is enforced
  // by the `enforce_individual_asset_single_kit` trigger rather than a
  // `@@unique([assetId])` constraint — QUANTITY_TRACKED assets are
  // intentionally free to belong to multiple kits at distinct slices.
  // The composite below still prevents listing the same asset twice in
  // the same kit.
  @@unique([assetId, kitId])
  @@index([kitId])
  @@index([organizationId])
}

model AssetLocation {
  id             String       @id @default(cuid())
  asset          Asset        @relation(fields: [assetId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  assetId        String
  location       Location     @relation(fields: [locationId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  locationId     String
  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  organizationId String

  quantity       Int          @default(1)

  // Manual-vs-kit-driven discriminator. NULL = manual placement (user-
  // managed via the manage-placements dialog or location picker).
  // Non-NULL = this row is driven by the referenced AssetKit (kit
  // membership) — the asset is at this location because the kit is.
  // Kit-driven rows are read-only in the manual-placement editors;
  // their quantity and location track the AssetKit and the kit's
  // `Kit.locationId`. The `onDelete: Cascade` means removing the asset
  // from the kit auto-deletes the kit-driven row. Mirrors the
  // `Custody.kitCustodyId` discriminator pattern.
  assetKit       AssetKit?    @relation(fields: [assetKitId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  assetKitId     String?

  createdAt      DateTime     @default(now())
  updatedAt      DateTime     @updatedAt

  // The "INDIVIDUAL asset at one location" cap is enforced by the
  // `enforce_individual_asset_single_location` trigger; the
  // `sum(quantity) <= Asset.quantity` invariant by the deferred
  // `enforce_asset_location_sum_within_total` constraint trigger.
  //
  // Uniqueness — split across two partial unique indexes created in
  // the migration SQL (Prisma can't express partial uniques in
  // schema, so they live in raw SQL):
  //   - "AssetLocation_manual_unique" → UNIQUE (assetId, locationId)
  //                                     WHERE "assetKitId" IS NULL
  //   - "AssetLocation_kit_unique"    → UNIQUE (assetKitId)
  //                                     WHERE "assetKitId" IS NOT NULL
  // The kit partial encodes "each AssetKit drives at most one
  // AssetLocation row" — since AssetKit itself is unique per
  // (assetId, kitId), this transitively caps kit-driven rows.
  @@index([locationId])
  @@index([organizationId])
  @@index([assetId])
  @@index([assetKitId])
}

// Units for reminder recurrence cadences ("every N <unit>"). Stored as
// unit + interval (not presets) so future custom cadences need no migration.
enum ReminderRecurrenceUnit {
  DAY
  WEEK
  MONTH
  YEAR
}

model AssetReminder {
  id                       String       @id @default(cuid())
  name                     String
  message                  String
  alertDateTime            DateTime
  activeSchedulerReference String?

  // Recurrence (null unit/interval = one-shot reminder, the default). For an
  // active recurring reminder, alertDateTime always holds the NEXT occurrence:
  // the worker advances it in place each time the reminder fires, keeping every
  // "upcoming" surface and the status/edit/cancel guards correct without forks.
  recurrenceUnit     ReminderRecurrenceUnit?
  recurrenceInterval Int?
  // IANA zone captured from client hints at create/edit so "every month at
  // 09:00" stays wall-clock-stable across DST. Null = UTC math (legacy rows).
  recurrenceTimezone String?
  // Optional series end (inclusive). Null = repeat until deleted.
  recurrenceEndsAt DateTime?

  organization             Organization @relation(fields: [organizationId], references: [id])
  organizationId           String
  asset                    Asset        @relation(fields: [assetId], references: [id], onDelete: Cascade)
  assetId                  String
  teamMembers              TeamMember[]
  createdBy                User         @relation(fields: [createdById], references: [id])
  createdById              String
  createdAt                DateTime     @default(now())
  updatedAt                DateTime     @updatedAt

  // Optimized indexes
  @@index([assetId, alertDateTime])
  // Keeping these indexes as they were added for a purpose
  @@index([name(ops: raw("gin_trgm_ops")), message(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([organizationId, alertDateTime, assetId])
  // For scheduler related queries
  @@index([alertDateTime, activeSchedulerReference])
  // Index for foreign key
  @@index([createdById])
}

model WorkingHours {
  id String @id @default(cuid())

  // Global enable/disable for the organization
  enabled Boolean @default(false)

  // Weekly schedule stored as JSON for better performance
  // Format: { "0": { "isOpen": true, "openTime": "09:00", "closeTime": "17:00" }, ... }
  // Keys are day numbers (0=Sunday, 1=Monday, etc.)
  // Times are wall-clock "HH:MM" (24-hour) — no timezone conversion. These
  // describe when the physical location is open, so they are interpreted as
  // local wall time, not UTC.
  weeklySchedule Json @default("{\"0\":{\"isOpen\":false},\"1\":{\"isOpen\":true,\"openTime\":\"09:00\",\"closeTime\":\"17:00\"},\"2\":{\"isOpen\":true,\"openTime\":\"09:00\",\"closeTime\":\"17:00\"},\"3\":{\"isOpen\":true,\"openTime\":\"09:00\",\"closeTime\":\"17:00\"},\"4\":{\"isOpen\":true,\"openTime\":\"09:00\",\"closeTime\":\"17:00\"},\"5\":{\"isOpen\":true,\"openTime\":\"09:00\",\"closeTime\":\"17:00\"},\"6\":{\"isOpen\":false}}")

  // Relationships
  organization   Organization @relation(fields: [organizationId], references: [id], onUpdate: Cascade, onDelete: Cascade)
  organizationId String       @unique

  // Only overrides need separate table for better querying
  overrides WorkingHoursOverride[]

  // Datetime
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // Index for foreign key
  @@index([organizationId])
}

// Keep overrides separate for efficient date-based queries
model WorkingHoursOverride {
  id String @id @default(cuid())

  date   DateTime @db.Date
  isOpen Boolean  @default(false)

  // Wall-clock "HH:MM" (24-hour) — no timezone conversion (see WorkingHours).
  openTime  String? // Format: "09:00"
  closeTime String? // Format: "17:00"
  reason    String?

  workingHours   WorkingHours @relation(fields: [workingHoursId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  workingHoursId String

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([workingHoursId, date])
  @@index([workingHoursId, date])
  @@index([date, isOpen])
}

