  auditAssetId String?

  uploadedBy   User?   @relation("AuditImageUploader", fields: [uploadedById], references: [id], onDelete: SetNull, onUpdate: Cascade)
  uploadedById String?

  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade, onUpdate: Cascade)
  organizationId String

  // Datetime
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // Indexes for performance
  @@index([auditSessionId])
  @@index([auditAssetId])
  @@index([organizationId])
  @@index([uploadedById])
}

/// How a membership's role came to change.
enum RoleChangeSource {
  /// An owner or administrator changed it in the team settings.
  MANUAL
  /// The member's identity-provider groups changed it at sign-in.
  SSO
}

model RoleChangeLog {
